import React, { useEffect, useState } from 'react'
import axios from 'axios';
import Toast from '../../components/toast';
import { TrashIcon, PencilSquareIcon, ArrowDownIcon} from '@heroicons/react/24/solid'



const MusicPlaylist = () => {
    const[error, setError] = useState('')
    const [playlists, setPlaylistss] = useState([])
    const [editplaylist, setEditplaylist] = useState({})
    const [highlightedId, setHighlightedId] = useState(null)
    const [musics, setMusics] = useState([])
    const [musicsplayback, setMusicsplayback] = useState([])
    const [editmusics, setEditMusics] = useState({})
    const [openIndex, setOpenIndex] = useState(null)
     const[data, setData] = useState({name:'', description:'', type:'', files:''})
    const [newplaylists, setNewPlaylists] = useState({
      name:'',
      description:'',
      musics:[],
      duration:"00:00:00"
    })
    

    useEffect(() => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.get(`${baseUrl}/musicplaylist`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log( response.data);
        setPlaylistss(response.data.data);
      })
      axios.get(`${baseUrl}/musicplayback`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log( response.data);
        setMusicsplayback(response.data.data);
      })
    }, [])
    
    const handleHighlight = (id) => {
      setHighlightedId(id);
      setTimeout(() => {
        setHighlightedId(null);
      }, 4000);
    }

  
    const toggleOpen = (item) => {
      console.log("Playlist", item)
      setOpenIndex(openIndex === item.id ? null : item.id)
      setEditplaylist(item)
      setMusics(item.musics)
    }


    const deletePlaylist =(id) => {

      const baseUrl = process.env.REACT_APP_BASE_API
      const token =  localStorage.getItem("authToken");
      axios.delete(`${baseUrl}/musicplaylist/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("deletePlaylist", response);
        setPlaylistss(response.data.data)
      })
    }

   const updatePlaylist =() =>{
      console.log("Start update ...")
      const baseUrl = process.env.REACT_APP_BASE_API
      const token =  localStorage.getItem("authToken")
      const musicIds = musics.map(m => m.id)
      const updated = { ...editplaylist, musics: musicIds }
      setEditplaylist(updated)
      axios.put(`${baseUrl}/musicplaylist/${editplaylist.id}`, updated, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("Update responce", response.data.data);
          handleHighlight(editplaylist.id)
      })
    }

    const deleteMusicFromList =(id) => {
      setMusics(prev => prev.filter(x => x.id !== id))
    }

    const addToList = (id) => {
      const newItem = musicsplayback?.find((x) => x.id === id)
      if (!newItem) return

      const alreadyExists = newplaylists.musics.some((x) => x.id === id)
      if (alreadyExists) return

      setNewPlaylists((prev) => ({...prev, musics: [newItem, ...prev.musics]}))
    }

    const createPlaylist =() =>{
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      const musicIds = newplaylists.musics.map(m => m.id)
      const newSch = { ...newplaylists, musics: musicIds }
      axios.post(`${baseUrl}/musicplaylist`, newSch, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("new musicplaylist", response.data);
        setPlaylistss(response.data.data)
        
      })
    }


    useEffect(() => {
      console.log("data", data);
    }, [data])



    const handleUpload= (event) => {
      setError('')
      const file = event.target.files[0]
      
      const allowedTypes = ['audio/wav']
      
      if (file && !allowedTypes.includes(file.type)) {
        setError("Please select a valid file (.wav)")
        event.target.value = ''
      }
      else{

        setData({ ...data, type: 'WAVE', files: event.target.files[0] })
      }
      
    }

    const submitUpload = () => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token = localStorage.getItem("authToken");

      const formData = new FormData();
      formData.append('files[]', data.files); // ✅ Correct key
      formData.append('name', data.name);
      formData.append('description', data.description);
      formData.append('type', 'music'); // ✅ Force correct type

      axios.post(`${baseUrl}/musicplayback`, formData, {
        headers: {
          'Authorization': `${token}`,
          'Content-Type': 'multipart/form-data',
        }
      })
      .then((response) => {
        console.log("Upload success", response.data);
        document.getElementById('importMusic').close();

        // ✅ Update UI with new music
        setMusicsplayback(prev => [...prev, ...response.data.data]);

        // ✅ Reset form
        setData({name:'', description:'', type:'music', files:''});
      })
      .catch((error) => {
        console.error("Upload error", error);
      });
    }
    
    const deleteMusic = (id) => {
      const baseUrl = process.env.REACT_APP_BASE_API
      const token =  localStorage.getItem("authToken");
      axios.delete(`${baseUrl}/musicplayback/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("delete music", response);
        setMusicsplayback(response.data.data)
      })
    }




  return (
    <div className='flex h-full gap-10'>
      <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Playlist</span>
         {playlists?.map((item) => {
            return(
              <div key={item.id} className='flex flex-col mb-3'>
                <div className={`flex items-center justify-between h-10 rounded-md ${ highlightedId === item.id ? 'blink-green' : 'bg-base-200'} px-3`}>
                  <span>{item.name}</span>
                  <div className='flex gap-2 items-center'>
                    <button onClick={() => toggleOpen(item)} className='text-info' >
                    <PencilSquareIcon className='w-5'/></button>
                    <button onClick={() => deletePlaylist(item.id)} className='text-error'><TrashIcon className='w-5'/></button>
                  </div>
                </div>
                 <div className={`${openIndex === item.id ? 'h-80' : 'h-0'} relative bg-slate-200 overflow-hidden transition-all duration-500 ease-in-out`}>
                  <div className='flex'>
                     <div className='flex flex-col gap-5 p-5'>
                      <div className='flex gap-10 mb-5'>
                        <div className='flex items-center gap-2'>
                            <span>Schedule Name: </span>
                            <input onChange={(x) => setEditplaylist(prev => ({...prev, name: x.target.value}))} value={editplaylist?.name} name='name' type="text"  autoFocus />
                        </div>
                        <div className='flex items-center gap-2'>
                            <span>Description: </span>
                            <input onChange={(x) => setEditplaylist(prev => ({...prev, description: x.target.value}))} value={editplaylist?.description} name='description' type="text"  autoFocus />
                        </div>
                        <div className='flex items-center gap-2 bg-base-300/70 p-1 rounded-lg'>
                            <span>Total duration: {item?.duration}</span>
                        </div>
                      </div>

                      <div className='flex flex-col gap-2 justify-between text-sm my-10'>
                        {musics?.map((music) => {
                          return(
                            <div id={`${item.id}-${music.id}`} key={music.id} className='flex items-center gap-10'>
                              <span>{music?.name}</span>
                              <audio controls className="w-96 h-10" style={{ height: '30px' }} >
                                <source src={`${process.env.REACT_APP_AFTERSOX + music.path}`} type="audio/mpeg" />
                              </audio>
                              <span>{music?.duration}</span>
                              <button onClick={() => deleteMusicFromList(music.id)} className='text-info'><TrashIcon className='w-5'/></button>
                            </div>
                          )
                        })}
                          
                      </div>
                    
                    </div>
                  </div>
                  <button onClick={updatePlaylist} className='absolute bottom-2 right-2 btn btn-success btn-xs text-base-100 px-5'>SAVE</button>
                </div>
              </div>
            )})}
         
      </div>


      <div className='flex flex-col gap-5 justify-between w-4/12'>
        <div className='relative h-3/5 border rounded-lg p-5 bg-base-200'>
            <span className='absolute left-8 bg-base-300 px-5 border rounded-lg' style={{top:-13}}>Audio List</span>
            <div className='w-full h-full overflow-auto scrollbar pt-3'>
              {musicsplayback?.map((item, key) => {
                return(
                  <div key={key} className='flex justify-between p-2 mb-2 bg-base-100 rounded-lg'>
                    <span>{item?.name}</span>
                    <audio controls className="w-60 h-10" style={{ height: '30px' }} >
                      <source src={`${process.env.REACT_APP_AFTERSOX + item.path}`} type="audio/mpeg" />
                    </audio>
                    <button onClick={() => deleteMusic(item.id)} className='text-info'><TrashIcon className='w-5'/></button>
                    <button onClick={() => addToList(item.id)} className='flex items-center justify-center bg-accent rounded-full w-6 h-6 text-2xl pb-1'>+</button>
                  </div>
                )
              })}
            </div>
          </div>
          <div className='flex flex-col gap-5 h-2/5 border rounded-lg p-5 bg-base-200'>
              <div className='flex gap-2 text-sm items-center'>
                <span>Playlist name</span>
                <input type='text' onChange={(e) => setNewPlaylists(prev => ({...prev, name: e.target.value}))} className='w-40'/>
                <span>Description</span>
                <input type='text' onChange={(e) => setNewPlaylists(prev => ({...prev, description: e.target.value}))} className='w-40'/>
              </div>
              <span>Music List</span>
              <div className='flex gap-2 flex-wrap bg-base-300/50 p-5 w-full h-full rounded-lg'>
                {newplaylists?.musics?.map((item, key) => {
                  return(
                    <div key={key} className='flex gap-5 justify-between h-10 p-2 mb-2 bg-base-300/50 rounded-lg'>
                      <span>{item.name}</span>
                      <button className='bg-error rounded-full w-6 h-6'>X</button>
                    </div>
                  )
                })}
              </div>
          </div>
          <div className='flex gap-5'>
            <button onClick={createPlaylist} className="btnd bg-success w-28">Submit</button>
            <button onClick={() => (document.getElementById('importMusic')).showModal()} className="btnd bg-accent w-40">Import New Music</button>
          </div>
      </div>

      <dialog id="importMusic" className="modal">
        <div className="modal-box w-11/12 max-w-2xl bg-base-100">
          <div className="relative border rounded-lg p-5">
          <span className='absolute left-8 bg-info-content px-5 rounded-lg text-white' style={{top:-15}}>Import Music</span>
            <div className="flex flex-col gap-5">
           
              <div className='flex flex-col gap-5 modal-action'>
                <div className='flex flex-col gap-5 flex-1 gap-2'>
                  <input type='text' onChange={(e) => setData({ ...data, name: e.target.value })} placeholder='Name' className='w-56'/>
                  <input type='text' onChange={(e) => setData({ ...data, description: e.target.value })} placeholder='Description' className='w-56'/>
                  <input type="file" onChange={handleUpload} className="file-input file-input-bordered w-full max-w-xs" accept=".mp4"/>
                
                </div>
                <span className='text-error'>{error}</span>
                <div className='flex w-full justify-end gap-3'>
                  <form method="dialog">
                    <button className="btnd w-20 bg-error">Close</button>
                  </form>
                  <button onClick={submitUpload} className="btnd w-20 bg-success">Update</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </dialog>

    </div>
  )
}

export default MusicPlaylist