import React, { useState } from 'react'
import { useWebSocket } from '../../../context/WebSocketContext'

const PlayMediaModul = ({playZones, playlists}) => {

    const [openId, setOpenId] = useState(null)
    const [ data, setData] = useState([])
    const [chime, setChime] = useState('1')
    const { sendMessage } = useWebSocket()
    
    const selectAccordion = (id) => {
        console.log("Id", id)
        setData(playlists.find((x) => x.id == id))
      
    };
    
    const handleToggle = (id) => {
        if (openId === id) {
          setOpenId(null)
        } else {
          setOpenId(id)
        }
    }


    const handlePlayMedia = () => {
        console.log("Name", playlists)

        var randomId = Math.floor(1000 + Math.random() * 9000)
        let message = {
            messageId: randomId,
            commandStr: "playmedia",
            dataArr: [
              {
                mediaPlaylistName: data.name,
                mediaPlaylistDetails: data.media_list,
                pidlist: ["SA01-GDU06-CC1-D1","SA01-GDU06-CC1-D2"],
                priority: "12",
                timeoutms: "60000",
                user: "Amir"
              },
            ],
            deviceSelectionStr: "PIDS_TCS",
            moduleSelectionStr: "PLAY_MEDIA_MODAL",
          };
        sendMessage(JSON.stringify(message))
    }

 

  return (
    <dialog id="playMedia" className="modal">
        <div className="modal-box w-full max-w-3xl bg-neutral">
            <div className="relative border rounded-lg p-5">
                <span className='absolute left-8 bg-base-100 px-5 text-warning border rounded-lg' style={{top:-15}}>Play Media</span>
                <form method="dialog" className="flex flex-col gap-5 pt-3">
                    <div>
                        {playZones.map((zone) => {
                            return(
                                <div className="w-28 h-5 badge badge-secondary badge-outline" key={zone}>{zone}</div>
                            )
                        })}
                    </div>
                    <select className='bg-secondary' value={1} onChange={(e) => setChime(e.target.value)}>
                        <option value="0">No chime</option>
                        <option value="1">chime 1</option>
                        <option value="2">chime 2</option>
                        <option value="3">chime 3</option>
                    </select>
                    <div className='flex flex-col gap-2 h-[400px]'>
                        {playlists.map((each) => {
                            return(
                                <div key={each.id}  className='flex gap-5'>
                                    <div  key={each.id} className={`collapse collapse-plus bg-slate-800 ${openId === each.id ? "h-auto" : "h-10"}`}>
                                        <input type="checkbox" checked={openId === each.id} onChange={() => handleToggle(each.id)} />
                                        <div className="flex justify-between text-md text-warning gap-5 collapse-title font-bold">
                                            <span>{each.name}</span>
                                        </div>
                                        <div className={`collapse-content ${openId === each.id ? 'h-auto' : 'h-0 overflow-hidden'}`}>
                                            <table className='w-full'>
                                            <thead className='text-left bg-black'>
                                                <tr className='border-b'>
                                                <th>Name</th>
                                                <th>Audio Location</th>
                                                <th className='w-40'>Play Demo</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {each.medias?.map((audio, ind) => {
                                                    return(
                                                    <tr key={ind} className='h-10'>
                                                    <td>{audio.name}</td>
                                                    <td>{audio.path}</td>
                                                    <td>
                                                    <audio controls className="w-52 h-10" style={{ height: '30px' }} >
                                                        {/* <source src={`${process.env.NEXT_PUBLIC_AFTERSOX}/${audio.path}.wav`} type="audio/mpeg" /> */}
                                                        <source src={audio.path} type="audio/mpeg" />
                                                    </audio>
                                                    </td>
                                                    </tr>
                                                    )
                                                })}
                                            </tbody>
                                            </table>
                                            
                                        </div>
                                    </div>
                                    <div className='flex justify-center items-center bg-slate-800 w-10 h-10 rounded-lg'>
                                        <input onChange={() => selectAccordion(each?.id)} id={each.id} type="radio" name="radio-1" className="radio" />
                                    </div>
                                </div>
                            )
                        })

                        }
                    </div>
                    <div className='flex gap-5'>
                        <button className="btnd w-20 bg-error">Close</button>
                        <button onClick={handlePlayMedia} className={`btnd w-20 ${data.length == 0 ? "bg-slate-600" : "bg-success"}`} disabled={data.length == 0}>Play</button>
                    </div>

                </form>
            </div>
        </div>
    </dialog>
  )
}

export default PlayMediaModul