import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {ExclamationCircleIcon, CheckCircleIcon} from '@heroicons/react/24/solid'
import axios from 'axios';


const StatusTree = ({ title }) => {

    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const baseUrl = process.env.REACT_APP_BASE_API;
        const token =  localStorage.getItem("authToken");
        axios.get(`${baseUrl}/healthcheckitems`, { headers: { Authorization: `${token}`}}).then((response) => {
          console.log("Status tree",response.data.data )
            setData(response.data.data.sort((a, b) => b.id - a.id));
          if(response.status === 200){
            setLoading(true)
          }
          else{
            setLoading(false)
          }
        });
    }, [])
    




    return (
        <motion.div className="relative w-full border px-5 py-10 rounded-lg min-h-64 bg-base-200">
            <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>{title}</span>
            { loading ? data.map((item, key) => {
                return(
                    <div key={key} tabIndex={0} className="collapse bg-neutral mb-3">
                        <div className="text-md gap-5 collapse-title min-h-12 font-bold">{item.locationName}</div>
                        <div className="collapse-content">
                            {item.items?.map((item, ind) => {
                                return(
                                    <div key={ind} className='flex justify-between p-2 border-t'>
                                        <span className='w-40'>{item.hostName}</span>
                                        <span>{item.sysType}</span>
                                        <span>{item.hostStatus == "Success" ? <CheckCircleIcon className='w-7 text-success'/> : <ExclamationCircleIcon className='w-7 text-error'/> }</span>
                                    </div>
                                )
                            })}
                        </div>
                    </div>
                )
            } )
          
            : 
            <div className='flex flex-col justify-center items-center w-full h-full'>
                <span className="text-info font-bold">Loading</span>
                <span className="loading loading-ring loading-lg text-info font-bold"></span>
            </div>
        
        }

        </motion.div>
    );
};

export default StatusTree;


