import React, { useEffect, useState } from 'react'
import openSocket from 'socket.io-client';
import {Link, useLocation } from 'react-router-dom';
import DetectNetwork from "../utils/detectNetwork";
import { useWebSocket } from '../context/WebSocketContext';
import { Squares2X2Icon, SpeakerWaveIcon, TvIcon, BellAlertIcon, DocumentChartBarIcon, RectangleGroupIcon, FilmIcon } from '@heroicons/react/24/solid'
import axios from 'axios';

function Header() {

  const location  = useLocation()
  const currentPath = location.pathname
  const [paServerNodeA, setPaServerNodeA] = useState(true)
  const [paServerNodeB, setPaServerNodeB] = useState(false)

  
  const [socket, setSocket] = useState(null);
  const networkState = DetectNetwork();
  const  online  = networkState;
  
  
  const { messages, setMessages } = useWebSocket();
  const [alarmsCount, setAlarmsCount] = useState({"p1":0, "p2":0, "p3":0, "p4":0,});

  const [modules, setModules] = useState([])
  const [menus, setMenus] = useState([])

  useEffect(() => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.get(`${baseUrl}/modules`, { headers: { Authorization: `${token}`}}).then((response) => {
        setModules(response.data.data)
        
      })
    }, [])

    useEffect(() => {
      if (modules.length === 0) return
      const segments = location.pathname.split("/").filter(Boolean)
      const key = segments[0]
      const filtered = modules.filter((x) => x.module === key?.toUpperCase())
      setMenus(filtered)
    }, [modules, location])


  useEffect(() => {
    if(messages.length > 0){
      //let parsedMessage
      //parsedMessage = JSON.parse(messages)
      switch (messages.commandStr) {
        case 'Alarm':
            const baseUrl = process.env.REACT_APP_BASE_API;
            const token =  localStorage.getItem("authToken");
            axios.get(`${baseUrl}/getalarmbypriority`, { headers: { Authorization: `${token}`}}).then((response) => {
              setAlarmsCount((alarmsCount) =>({...alarmsCount, p1:response.data.pr1, p2:response.data.data.pr2, p3:response.data.data.pr3, p4:response.data.data.pr4}))
            });
          break;
        
        default:
            break;
      }
      setMessages([])
    }
  }, [messages])


  const logout = () => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/logout`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("logout", response)
      if(response.status === 204){
        localStorage.removeItem("user");
        localStorage.removeItem("authToken");
    
        document.cookie = 'authToken=; Max-Age=-1; path=/; secure; SameSite=Strict';
        window.location.href = '/login';
      }
    });
  }

  /**
   * Connect to Socket IO
   */
  const connectToSocketIO = () => {
    const serversSocket = openSocket('localhost:7010', { transports: ['websocket'] });
    serversSocket.on('poll_server', (data) => {
      data.forEach((element) => {
        switch (element.ip) {
            case '10.103.102.31':
                element.status == "fail" ? setPaServerNodeA(false) : setPaServerNodeA(true)
                break;
            case '10.103.104.31':
              element.status == "fail" ? setPaServerNodeB(false) : setPaServerNodeB(true)
                break;
            default:
              break;
        }
    });

    })

    serversSocket.on('disconnect', (data) => {
      console.log('Disconnected from server');
    });

    serversSocket.on('reconnect', (data) => {
      console.log('Reconnected to server');
    });
  }


  useEffect(() => {
    const serversSocket = openSocket('localhost:7010', { transports: ['websocket'] });
    setSocket(serversSocket);
  }, [online])


  useEffect(() => {
    if (socket !== null) {
      socket.addEventListener("connect", () => {
        console.log("Socket connected");
        setSocket(socket);
        connectToSocketIO();
      });

      socket.addEventListener("disconnect", () => {
        console.log("Socket closed unexpectedly");
        setSocket(null);
      });
    }

  }, [socket])


  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/getalarmbypriority`, { headers: { Authorization: `${token}`}}).then((response) => {
      setAlarmsCount((alarmsCount) =>({...alarmsCount, p1:response.data.data.pr1, p2:response.data.data.pr2, p3:response.data.data.pr3, p4:response.data.data.pr4}))
    });
  }, [])
  
  const handleSelectMenu = (key) => {
    setMenus(modules.filter(x => x.module === key))
  }




  return (
    <>
    <nav className='fixed top-0 left-0 w-full flex flex-col justify-between bg-primary text-white'>
      <div className='flex justify-between w-full h-24 items-center border-b'>
        <div className='w-2/12 py-1 pl-5'>
          <div className='bg-white w-28'>
            <img src='/logo.png' alt='logo' width={100}/> 
          </div>
        </div>
        <div className='flex w-full justify-between items-center pr-5'>
            <div className='flex gap-2'>
              <div className="alarm-box bg-error">{alarmsCount.p1}</div> 
              <div className="alarm-box bg-warning">{alarmsCount.p2}</div> 
              <div className="alarm-box bg-warning-content text-black">{alarmsCount.p3}</div> 
              <div className="alarm-box bg-success">{alarmsCount.p4}</div>
            </div>
            <div className='flex gap-2 items-center'>
              <div className={`flex justify-between pl-2 items-center rounded-xl w-28 h-7 bg-success ${!paServerNodeA ? 'animate-blinkingBg':""}`} >
                <span className="">Server</span>
                <div className={`bg-accent text-white w-6 h-6 rounded-full mx-1 text-center `} >A</div>
              </div>
              <div className={`flex justify-between pl-2 items-center rounded-xl w-28 h-7 bg-success ${!paServerNodeB ? 'animate-blinkingBg':""}`} >
                <span className="">Server</span>
                <div className={`bg-accent text-white w-6 h-6 rounded-full mx-1 text-center `} >B</div>
              </div>

              <div className="dropdown dropdown-end ml-5">
                <div tabIndex={0} role="button" className="btn btn-ghost btn-circle avatar">
                <div className="w-8 rounded-full">
                  <img alt="user" src="/user.jpg" />
                </div>
                </div>
                <ul tabIndex={0} className="menu menu-sm dropdown-content bg-base-300 rounded-box z-[1] mt-3 w-52 p-2">
                  <li><button onClick={logout}>Logout</button></li>
                </ul>
              </div>

              <div className="dropdown dropdown-end ml-2">
                <Link className="rounded-full" to="/config/help">
                  <img className='w-8' alt="flag" src="/images/icons/help.png" />
                </Link>
              </div>
              <Link to='/config'>
                <img className='w-8' alt="flag" src="/images/icons/setting.png" />
              </Link>
            </div>
        </div>
      </div>
      <div className='flex mx-auto gap-3 h-12 items-center'>
        <div className='flex w-full gap-3 px-10'>
                {menus?.map((menu) => {
                    return(
                      <Link key={menu.id} to={menu.route} className={`bg-base-300 btn_link`} href='/papids'>{menu.name}</Link>
                    )
                })}
            </div>
      </div>
    </nav>
    <div className='fixed left-0 top-[180px] flex flex-col bg-neutral w-[60px] h-[600px] rounded-r-xl items-center text-white'>
        <Link to='/' onClick={handleSelectMenu} className={`${currentPath == "/" && "bg-neutral-content"} flex items-center justify-center w-full h-14 rounded-tr-xl`}>
            <img className='w-10' src={`/images/icons/station.png`} />
        </Link>
        <Link to='/dashboard' onClick={() => handleSelectMenu('dashboard')} className={`${currentPath == "/dashboard" && "bg-neutral-content"} flex items-center justify-center w-full h-14`}>
            <Squares2X2Icon className={`${currentPath == "/dashboard" ? "text-white" : "text-base-300"} w-10`} />
        </Link>

        <div className='relative w-full h-1 border-b my-3'>
          <span className='absolute top-[-10px] left-2 px-1 bg-neutral'>Main</span>
        </div>

        <Link to='/papids' onClick={() => handleSelectMenu('PAPIDS')} className={`${currentPath == "/papids" && "bg-neutral-content"} flex items-center justify-center w-full h-14`}>
            <RectangleGroupIcon className={`${currentPath == "/papids" ? "text-white" : "text-base-300"} w-10`} />
        </Link>
        <Link to='/pa' onClick={() => handleSelectMenu('PA')} className={`${currentPath == "/pa" && "bg-neutral-content"} flex items-center justify-center  w-full h-14`} >
            <SpeakerWaveIcon className={`${currentPath == "/pa" ? "text-white" : "text-base-300"} w-10`} />
        </Link>
        <Link to='/pids'onClick={() => handleSelectMenu('PIDS')} className={`${currentPath == "/pids" && "bg-neutral-content"} flex items-center justify-center  w-full h-14`}>
            <TvIcon className={`${currentPath == "/pids" ? "text-white" : "text-base-300"} w-10`} />
        </Link>
        <Link to='/alarm' onClick={() => handleSelectMenu('ALARM')} className={`${currentPath == "/alarm" && "bg-neutral-content"} flex items-center justify-center  w-full h-14`}>
            <BellAlertIcon className={`${currentPath == "/alarm" ? "text-white" : "text-base-300"} w-10`} />
        </Link>
        <Link to='/log' onClick={() => handleSelectMenu('LOG')} className={`${currentPath == "/log" && "bg-neutral-content"} flex items-center justify-center  w-full h-14`}>
            <DocumentChartBarIcon className={`${currentPath == "/log" ? "text-white" : "text-base-300"} w-10`} />
        </Link>

        <div className='relative w-full h-1 border-b my-3'>
          <span className='absolute top-[-10px] left-3 px-1 bg-neutral'>Ads</span>
        </div>

        <Link to='/ads' onClick={() => handleSelectMenu('ADS')} className={`${currentPath == "/ads" && "bg-neutral-content"} flex items-center justify-center  w-full h-14`}>
            <FilmIcon className={`${currentPath == "/ads" ? "text-white" : "text-base-300"} w-10`} />
        </Link>
    </div>


    </>
  )
}

export default Header