import React, { createContext, useContext, useState, useEffect } from 'react';

// Create an authentication context
const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Function to check JWT validity (by decoding and checking the expiration)
  const isTokenValid = (token) => {
    if (!token) return false;
    const decoded = JSON.parse(atob(token.split('.')[1])); // Decode JWT payload
    const expiryTime = decoded.exp * 1000; // exp is in seconds, convert to milliseconds
    return expiryTime > Date.now(); // Check if token has expired
  };

  // Function to load the token and check if it's valid
  const checkAuthToken = () => {
    const token = localStorage.getItem('authToken'); // Get the token from localStorage
    if (token && isTokenValid(token)) {
      setIsAuthenticated(true); // Set the authentication state to true if valid
    } else {
      setIsAuthenticated(false); // If token is invalid or not found, set to false
    }
  };

  const login = (token) => {
    localStorage.setItem('authToken', token); // Save token to localStorage
    setIsAuthenticated(true); // Set authentication state to true
  };

  const logout = () => {
    localStorage.removeItem('authToken'); // Remove token from localStorage
    setIsAuthenticated(false); // Set authentication state to false
  };

  // Check the token validity when the component mounts
  useEffect(() => {
    checkAuthToken(); // Verify the token when the app loads
  }, []);

  return (
    <AuthContext.Provider value={{ isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};
