import React, { useEffect, useState } from 'react'



const StepOne = ({handleBack, handleNext, step, data, setData}) => {

  const [errors, setErrors] = useState({ audioName: '', textBM: '', textEN: '', textMA: '', textHI: '' })

  const validation = () => {
    let valid = true
    let newErrors = { audioName: '', textBM: '', textEN: '', textMA: '', textHI: '' }
    for (let key in errors) {
      if (data.hasOwnProperty(key) && data[key] === '') {
        newErrors[key] = `${key} cannot be empty`
        valid = false
      }
    }
    setErrors(newErrors);
    if(valid){handleNext(step)}
  }

  return (
    <div className='flex flex-col justify-between w-full items-center'>

      <div className='flex flex-col gap-5 w-full items-center'>
        <span className='mb-5 text-2xl'>Create new audio</span>
        <div className='flex w-4/12 justify-between items-center gap-10'>
          <span className={`w-52 ${errors.audioName != '' ? "text-error" : ""}`}>Audio Name</span>
          <input onChange={(e) => setData((prevState) => ({ ...prevState, audioName: e.target.value }))} defaultValue={data.audioName ? data.audioName : "testAudio"} className='flex-1' type='text' />
        </div>
        <div className='flex w-4/12 justify-between items-center gap-10'>
          <span className={`w-52 ${errors.textBM != '' && "text-error"}`}>PIDS text (Bahasa Malaysia)</span>
          <input onChange={(e) => setData((prevState) => ({ ...prevState, textBM: e.target.value }))} defaultValue={data.textBM  ? data.textBM : "text for Malay"} className='flex-1' type='text' />
        </div>
        <div className='flex w-4/12 justify-between items-center gap-10'>
          <span className={`w-52 ${errors.textEN != '' && "text-error"}`}>PIDS text (Bahasa English)</span>
          <input onChange={(e) => setData((prevState) => ({ ...prevState, textEN: e.target.value }))} defaultValue={data.textEN  ? data.textEN : "text for English"} className='flex-1' type='text' />
        </div>
        <div className='flex w-4/12 justify-between items-center gap-10'>
          <span className={`w-52 ${errors.textMA != '' && "text-error"}`}>PIDS text (Bahasa Mandarin)</span>
          <input onChange={(e) => setData((prevState) => ({ ...prevState, textMA: e.target.value }))} defaultValue={data.textMA  ? data.textMA : "text for Mandarin"} className='flex-1' type='text' />
        </div>
        <div className='flex w-4/12 justify-between items-center gap-10'>
          <span className={`w-52 ${errors.textHI != '' && "text-error"}`}>PIDS text (Bahasa Hindi)</span>
          <input onChange={(e) => setData((prevState) => ({ ...prevState, textHI: e.target.value }))} defaultValue={data.textHI  ? data.textHI : "text for Hindi"} className='flex-1' type='text' />
        </div>
      </div>

      <div className='flex gap-5'>
        <button onClick={() => handleBack(step)} className='w-20 btn btn-sm btn-info' disabled>Back</button>
        <button onClick={() => validation()} className='w-20 btn btn-sm btn-info' >Next</button>
      </div>
    
  </div>
  )
}

export default StepOne