import './style.css';
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom'; // Import useNavigate
import { useAuth } from '../../authContext'; // Import the useAuth hook

const LoginPage = () => {
  const [username, setUsername] = useState('gis');
  const [password, setPassword] = useState('gispassword');
  const [error, setError] = useState('');
  const navigate = useNavigate(); // Use useNavigate hook instead of useHistory
  const { login } = useAuth()

  // Handle form input changes
  const handlEmailChange = (e) => setUsername(e.target.value);
  const handlePasswordChange = (e) => setPassword(e.target.value);

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Clear previous errors
    setError('');

    // Check if fields are empty
    if (!username || !password) {
      setError('Username and password are required.');
      return;
    }

    console.log("username", username)
    console.log("password", password)

    try {

      const baseUrl = process.env.REACT_APP_BASE_API
      //console.log("baseUrl", baseUrl)
      const response = await axios.post(`${baseUrl}/login`, {username:username, password: password})

      const { token, user, expires_in } = response.data
      //console.log("token", token)
      //console.log("user", user)
      //console.log("expires_in", expires_in)

      login(response.data.token)
      navigate('/')
    } catch (err) {
      setError('Invalid username or password');
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-base-300 to-base-100 p-4">
      <div className="bg-neutral p-10 rounded-2xl shadow-xl w-full max-w-sm">
        <h2 className="text-4xl font-bold text-primary mb-8 text-center">Welcome Back</h2>

        {error && (
          <div className="bg-error text-error-content p-4 rounded-lg mb-6">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label htmlFor="username" className="block text-primary-content mb-2 font-medium">Email Address</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={handlEmailChange}
              required
              className="w-full p-3 rounded-lg bg-base-200 focus:outline-none focus:ring-2 focus:ring-primary"
              placeholder="Enter your email"
            />
          </div>

          <div>
            <label htmlFor="password" className="block text-primary-content mb-2 font-medium">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={handlePasswordChange}
              required
              className="w-full p-3 rounded-lg bg-base-200 focus:outline-none focus:ring-2 focus:ring-primary"
              placeholder="Enter your password"
            />
          </div>

          <button
            type="submit"
            className="w-full p-3 rounded-lg bg-secondary text-primary-content font-semibold hover:bg-primary hover:text-base-content transition duration-300"
          >
            Sign In
          </button>
        </form>

        <p className="mt-6 text-center text-sm text-base-content">
          Don't have an account? <a href="#" className="text-primary hover:underline">Sign up</a>
        </p>
      </div>
    </div>
  );
};

export default LoginPage;
