import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon } from '@heroicons/react/24/solid'
import axios from 'axios'


const MessageSchedule = () => {

  const [highlightedId, setHighlightedId] = useState(null)
  const [messageSchedule, setMessageSchedule] = useState([])
  const [previwschedules, setPreviwSchedules] = useState({})
  const [schedules, setSchedules] = useState([])
  const [locations, setLocations] = useState([])
  const [playlists, setPlaylists] = useState([])
  const [newschedule, setNewschedule] = useState(
    { 
      name:"",
      description:"",
      playlist_id:"", 
      start_date:"", 
      end_date:"", 
      start_time:"", 
      end_time:"",
      interval:"",
      priority: 13,
      monday:false,
      tuesday:false,
      wednesday:false,
      thursday:false,
      friday:false,
      saturday:false,
      sunday:false,
      status:"Active",
      zones:[],  
      is_active: false 
    }
  )

  const [openIndex, setOpenIndex] = useState(null)

  const toggleOpen = (index) => {
    console.log("Sch id:", index)
    setOpenIndex(openIndex === index ? null : index)
    setPreviwSchedules(messageSchedule.find(x => x.id == index))
  };

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/mediaschedules`, { headers: { Authorization: `${token}`}}).then((response) => {
      setSchedules(response.data.data);
    })

    axios.get(`${baseUrl}/playlists`, { headers: { Authorization: `${token}`}}).then((result) => {
      setPlaylists(result.data.data);
    })

    axios.get(`${baseUrl}/getLocations`, { headers: { Authorization: `${token}`}}).then((resultLocation) => {
      setLocations(resultLocation.data)
    })
    axios.get(`${baseUrl}/schedules`, { headers: { Authorization: `${token}`}}).then((response) => {
        setMessageSchedule(response.data.sort((a, b) => b.id - a.id));
    })

  }, [])


  // useEffect(() => {
  //   console.log("previwschedules", previwschedules)
  // },[previwschedules])

  const handleHighlight = (id) => {
    setHighlightedId(id);
    setTimeout(() => {
      setHighlightedId(null);
    }, 4000);
  }

  const handleChange = (e) => {
    const { name, value, checked, type } = e.target
    setNewschedule((prev) => ({...prev,[name]: type === 'checkbox' ? checked : value}))
  }


  const updateZones = (id) => {
    console.log(id)
      setNewschedule(prev => {
        const isPresent = prev.zones.includes(id)
        return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
      })
  }

   const editZones = (id) => {
    console.log(id)
      setPreviwSchedules(prev => {
        const isPresent = prev.zones.includes(id)
        return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
      })
  }

   const updateSch =() =>{
    console.log("Start update ...")
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/schedules/${previwschedules.id}`, previwschedules, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Update responce", response.data.data);
        response.data.data.slice().sort((a, b) => b.id - a.id)
        handleHighlight(previwschedules.id)
    });

  }

  const createSch =() =>{
    console.log("Here")
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/schedules`, newschedule, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log( response.data);
      setMessageSchedule(response.data)
    });

  }

  const handleStatus =(item) => {
     const updatedItem = {...item, is_active: !item.is_active}
    item.is_active = !item.is_active
    delete updatedItem.created_on
    delete updatedItem.updated_on
    delete updatedItem.deleted_on
    delete updatedItem.created_by

    console.log("item", item);

    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/schedules/${item.id}`, updatedItem, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log( response.data);
      
    });
  }


  const handleEdite = (e) => {
    const { name, value, checked, type } = e.target
    setPreviwSchedules((prev) => ({...prev,[name]: type === 'checkbox' ? checked : value}))
  }

  return (
        <div className='flex h-[77vh] gap-10'>

        <div className='relative border rounded-lg w-8/12 p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Message Schedule List</span>
          <div className='overflow-auto scrollbar h-[72vh]'>
            {messageSchedule?.map((item, index) => {
              return(
                <div key={index} className='flex flex-col mb-3'>
                  <div className={`flex items-center justify-between h-10 rounded-md ${ highlightedId === item.id ? 'blink-green' : 'bg-base-100'} px-3`}>
                    <span>{item.name}</span>
                    <div className='flex gap-2 items-center'>
                      <input type="checkbox" defaultChecked={item.is_active} onChange={() => handleStatus(item)} className="toggle toggle-md h-5 toggle-success" />
                      <button onClick={() => toggleOpen(item.id)} className='text-info' ><PencilSquareIcon className='w-5'/></button>
                      <button className='text-error'><TrashIcon className='w-5'/></button>
                    </div>
                  </div>
                  <div className={`${openIndex === item.id ? 'h-full' : 'h-0'} relative border-t-4 bg-slate-200 overflow-hidden transition-all duration-500 ease-in-out`}>
                    <div className='flex flex-col gap-5 p-5'>
                        <div className='flex gap-10 mb-5'>
                          <div className='flex items-center gap-2'>
                              <span>Schedule Name: </span>
                              <input onChange={handleEdite} name='name' type="text" value={previwschedules?.name} autoFocus />
                          </div>
                          <div className='flex items-center gap-2'>
                              <span>Description: </span>
                              <input onChange={handleEdite} name='description' type="text" value={previwschedules?.description} autoFocus />
                          </div>
                          <div className='flex items-center gap-2'>
                              <span>Interval: </span>
                              <input onChange={handleEdite} name='interval' type="text" value={previwschedules?.interval} autoFocus />
                          </div>
                        </div>
                        <div className='flex gap-10 mb-5'>
                          <div className='flex items-center gap-2'>
                               <span className='w-2/5'>Playlist Name</span>
                              <select type='text'  onChange={handleEdite} name='playlist_id' value={previwschedules?.playlist_id?.toString()} className='input input-sm w-3/5'>
                                {playlists?.map((item) => {
                                  return(
                                    <option key={item.id} value={item.id}>{item.name}</option>
                                  )
                                })}
                              </select>
                          </div>
                          
                        </div>
                        <div className='flex gap-5 text-sm mb-5'>
                          <div className='flex gap-2 items-center'> 
                            <span>Monday :</span>
                            <input type="checkbox" checked={previwschedules?.monday} className="checkbox" />
                          </div>
                            <div className='flex gap-2 items-center'> 
                            <span>Tuesday :</span>
                            <input type="checkbox" checked={previwschedules?.tuesday} className="checkbox" />
                          </div>
                            <div className='flex gap-2 items-center'> 
                            <span>Wednesday :</span>
                            <input type="checkbox" checked={previwschedules?.wednesday} className="checkbox" />
                          </div>
                            <div className='flex gap-2 items-center'> 
                            <span>Thursday :</span>
                            <input type="checkbox" checked={previwschedules?.thursday} className="checkbox" />
                          </div>
                            <div className='flex gap-2 items-center'> 
                            <span>Friday :</span>
                            <input type="checkbox" checked={previwschedules?.friday} className="checkbox" />
                          </div>
                            <div className='flex gap-2 items-center'> 
                            <span>Saturday :</span>
                            <input type="checkbox" checked={previwschedules?.saturday} className="checkbox" />
                          </div>
                          <div className='flex gap-2 items-center'> 
                            <span>Sunday :</span>
                            <input type="checkbox" checked={previwschedules?.sunday} className="checkbox" />
                          </div>
                            
                        </div>
                        <div className='flex gap-5 text-sm'>
                          <div className='flex gap-2 items-center'> 
                            <span className='w-20'>Start Date :</span>
                            <input onChange={handleEdite} name='start_date' type="text" defaultValue={previwschedules?.start_date} />
                          </div>
                          <div className='flex gap-2 items-center'> 
                            <span className='w-20'>End Date :</span>
                            <input onChange={handleEdite} name='end_date' type="text" defaultValue={previwschedules?.end_date}/>
                          </div>
                          </div>
                            <div className='flex gap-5 text-sm'>
                          <div className='flex gap-2 items-center'> 
                            <span className='w-20'>Start time :</span>
                            <input onChange={handleEdite} name='start_time' type="text" defaultValue={previwschedules?.start_time}/>
                          </div>
                          <div className='flex gap-2 items-center'> 
                            <span className='w-20'>End time :</span>
                            <input onChange={handleEdite} name='end_time' type="text" defaultValue={previwschedules?.end_time}/>
                          </div>
                        </div>
                         <div className='flex flex-col gap-5 text-sm'>
                              <div className='w-6/12'>
                               {locations?.map((loc) => {
                                return(
                                  <div key={loc.id} className='flex gap-5 items-center p-2'>
                                    <span>{loc.location_name}</span>
                                    <div className='flex gap-3 wraper'>
                                      {loc.zones?.map((item) => {
                                        const isChecked = previwschedules?.zones?.includes(item.id) ?? false;
                                        return(
                                          <div key={item.id} className='flex flex-col justify-center'>
                                            <span>{item.zone}</span>
                                            <input onChange={() => editZones(item.id)} checked={isChecked} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                                          </div>
                                        )
                                      })}
                                    </div>
                                  </div>
                                )
                              })}
                              </div>
                           </div>
                    </div>
                    <button onClick={updateSch} className='absolute bottom-2 right-2 btn btn-success btn-xs text-base-100'>SAVE</button>
                  </div>
              </div>
              )
            })}
          </div>
        </div>

      <div className='flex flex-col gap-5 justify-between w-4/12'>
        <div className='relative h-full border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Create Schedule</span>
          <div className='flex flex-col gap-3 mt-5 overflow-auto scrollbar text-sm'>
            <div className='flex gap-5 items-center'>
                <span className='w-2/5'>Schedule Name</span>
                <input type='text' onChange={handleChange} name='name' placeholder='Schedule name' className='input input-sm w-3/5'/>
            </div>
            <div className='flex gap-5 items-center'>
                <span className='w-2/5'>Description</span>
                <input type='text' onChange={handleChange} name='description' placeholder='Description' className='input input-sm w-3/5'/>
            </div>
            <div className='flex gap-5 items-center mb-5'>
                <span className='w-2/5'>Playlist Name</span>
                <select type='text'  onChange={handleChange} name='playlist_id' value={previwschedules?.playlist_id?.toString()} className='input input-sm w-3/5'>
                  <option value='0'>Select play list</option>
                  {playlists?.map((item) => {
                    return(
                      <option key={item.id} value={item.id}>{item.name}</option>
                    )
                  })}
                </select>
            </div>

            <div className='flex gap-5 items-center'>
                <span className='w-3/12'>Start Date</span>
                <input type='text' placeholder='Start Date' onChange={handleChange} name='start_date' className='input input-sm w-3/5'/>
                <span className='w-3/12'>End Date</span>
                <input type='text' placeholder='End Date' onChange={handleChange} name='end_date' className='input input-sm w-3/5'/>
            </div>

            <div className='flex gap-5 items-center'>
                <span className='w-3/12'>Daily Start</span>
                <input type='text' placeholder='Start Time (HH:mm)' onChange={handleChange} name='start_time' className='input input-sm w-3/5'/>
                <span className='w-3/12'>Daily End</span>
                <input type='text' placeholder='End Time (HH:mm)'onChange={handleChange} name='end_time' className='input input-sm w-3/5'/>
            </div>
            <div className='flex gap-5 items-center my-5'>
                <span className='w-3/12'>Interval</span>
                <input type='text' placeholder='Interval' onChange={handleChange} name='interval' className='input input-sm w-1/5'/>
            </div>

            <div className='flex justify-between bg-base-100 rounded-md p-2'>
              <div className='flex flex-col'>
                <span className=''>Mon</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='monday'/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Tue</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='tuesday' checked={newschedule.tuesday}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Wen</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='wednesday' checked={newschedule.wednesday }/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Tue</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='thursday'  checked={newschedule.thursday }/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Fri</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='friday' checked={newschedule.friday }/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Sat</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='saturday' checked={newschedule.saturday }/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Sun</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={handleChange} name='sunday' checked={newschedule.sunday }/>
              </div>

            </div>

            <div className='flex flex-col bg-base-100 rounded-md'>
                  {locations?.map((loc) => {
                    return(
                      <div key={loc.id} className='flex gap-5 items-center p-2'>
                        <span>{loc.location_name}</span>
                        <div className='flex gap-3 wraper'>
                          {loc.zones?.map((item) => {
                            return(
                              <div key={item.id} className='flex flex-col justify-center'>
                                <span>{item.zone}</span>
                                <input onChange={() => updateZones(item.id)} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                              </div>
                            )
                          })}
                        </div>
                      </div>
                    )
                  })}
            </div>

          </div>
        </div>

        <div className='flex gap-5'>
            <button onClick={createSch} className="btnd bg-success w-28">Submit</button>
          </div>
      </div>
      </div>
  )
}

export default MessageSchedule