import { useState, useEffect } from "react";

/**
 * Custom React hook for detecting network connection status and retrieving network information.
 * @returns {Object} The network connection state object.
 * @property {Date} since - The timestamp indicating when the network status changed.
 * @property {boolean} online - Indicates whether the user is currently online.
 * @property {number} rtt - Round-trip time (in milliseconds) for the network connection.
 * @property {string} type - The type of network connection (e.g., "wifi", "cellular", "ethernet").
 * @property {boolean} saveData - Indicates whether the user's browser is in "data saver" mode.
 * @property {number} downLink - The estimated maximum downlink speed (in megabits per second).
 * @property {number} downLinkMax - The maximum downlink speed (in megabits per second).
 * @property {string} effectiveType - The effective type of the network connection (e.g., "slow-2g", "4g").
 */
function DetectNetwork() {  // Renamed to useDetectNetwork

    const [state, setState] = useState(() => {
        if (typeof window !== "undefined") {
            return {
                since: undefined,
                online: window.navigator.onLine,
                ...getNetworkConnectionInfo(),
            };
        }
        return {
            since: undefined,
            online: false,
        };
    });

    /**
     * Retrieves the network connection object from the browser.
     * @returns {Object|null} The network connection object or null if not available. 
     */
    function getNetworkConnection() {
        return (window.navigator.connection || window.navigator.mozConnection || window.navigator.webkitConnection || null );
    }

    /**
     * Retrieves network connection information from the network connection object.
     * @returns {Object} The network connection information. 
     */
    function getNetworkConnectionInfo() {
        const connection = getNetworkConnection(); 
        if (!connection) {
            return {};
        } 
        return {
            rtt: connection.rtt,
            type: connection.type,
            saveData: connection.saveData,
            downLink: connection.downLink,
            downLinkMax: connection.downLinkMax,
            effectiveType: connection.effectiveType,
        };
    }

    useEffect(() => {

        /**
         * Callback function for the "online" event.
         * Updates the state to indicate the user is online and sets the "since" property.
         */
        const handleOnline = () => {
            setState((prevState) => ({
                ...prevState,
                online: true,
                since: new Date().toString(),
            }));
        }; 
        
        /**
         * Callback function for the "offline" event.
         * Updates the state to indicate the user is offline and sets the "since" property.
         */
        const handleOffline = () => {
            setState((prevState) => ({
                ...prevState,
                online: false,
                since: new Date().toString(),
            }));
        }; 
        
        /**
         * Callback function for the "change" event on the network connection object.
         * Updates the state with the latest network connection information.
         */
        const handleConnectionChange = () => {
            setState((prevState) => ({
                ...prevState,
                ...getNetworkConnectionInfo(),
            }));
        }; 
        
        window.addEventListener("online", handleOnline);
        window.addEventListener("offline", handleOffline);

        const connection = getNetworkConnection(); 
        
        connection?.addEventListener("change", handleConnectionChange); 
        
        return () => {
            window.removeEventListener("online", handleOnline);
            window.removeEventListener("offline", handleOffline);
            connection?.removeEventListener("change", handleConnectionChange);
        };

    }, []);

    return state;
}

export default DetectNetwork;  // Also export with the new name
