import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon, PlayCircleIcon, PlusCircleIcon} from '@heroicons/react/24/solid'

const Users = () => {

    const [users, setUsers] = useState([])
    const [edituser, setEditUser] = useState({})
    const [groups, setGroups] = useState([])
    const [editGroup, setEditGroup] = useState({})
    const [groupData, setGroupData] = useState({"name":"", "description":""})

    useEffect(() => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.get(`${baseUrl}/getallusers`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("Users", response.data.data)
        setUsers(response.data.data);
      })
      axios.get(`${baseUrl}/groups`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("Groups", response.data.data)
        setGroups(response.data.data);
      })
    }, [])

    const handleCreateGroup = () => {
      console.log("groupData", groupData)

      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.post(`${baseUrl}/groups`, groupData, { headers: { Authorization: `${token}`}}).then((response) => {
        
        console.log("response", response.data)
         setGroups(response.data.data);
        document.getElementById('creategroup').close()
       })
    }

    const handleEditeGroup = (group) => {

      setEditGroup(group)
      document.getElementById('editgroup').showModal()
    }

     const handleEditeUser = (user) => {

      setEditUser(user)
      document.getElementById('edituser').showModal()
    }

    const handleUpdateUser = () => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.put(`${baseUrl}/users/${edituser.id}`, edituser, { headers: { Authorization: `${token}`}}).then((response) => {
        
        console.log("response update user", response.data.data)
        setUsers(response.data.data)
        document.getElementById('edituser').close()
      })
    }

    const handleUpdate = () =>{
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.put(`${baseUrl}/groups/${editGroup.id}`, editGroup, { headers: { Authorization: `${token}`}}).then((response) => {
        
      console.log("response", response.data)

        document.getElementById('editgroup').close()
      })
    }

    const handleDeleteUser = (id) =>{
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.delete(`${baseUrl}/users/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
        
        console.log("delete user response", response.data)
          setUsers(response.data.data)
          //document.getElementById('editgroup').close()
      })
    }

   const handleDeleteGroup = (id) =>{
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.delete(`${baseUrl}/groups/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
        
        console.log("delete group response", response.data)
          setUsers(response.data.data)
          //document.getElementById('editgroup').close()
      })
    }

    useEffect(() => {
        console.log("edit edituser", edituser)
    }, [edituser])

  return (
    <>
      <div className='flex h-full gap-10'>
        <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro bg-base-200'>
            <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Media Playlist</span>
            <div className='flex flex-col mt-3 gap-2 overflow-auto scrollbar'>
                <table className='w-full'>
                    <thead className='text-left bg-base-300 p-2 text-base-100'>
                        <tr className='border-b'>
                          <th>Name</th>
                          <th>Email</th>
                          <th className='w-[100px] text-center'>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                      {users?.map((item) => {
                        return(
                          <tr key={item.id} className='h-10 border-b'>
                            <td>{item.name}</td>
                            <td>{item.email}</td>
                            <td className='flex gap-2 justify-center p-2'>
                                <button onClick={() => handleEditeUser(item)} className='text-info'><PencilSquareIcon className='w-5'/></button>
                                <button onClick={() => handleDeleteUser(item.id)} className='text-error'><TrashIcon className='w-5'/></button>
                            </td>
                          </tr>
                        )
                      })}
                    </tbody>
                </table>
            </div>
        </div>

        <div className='flex flex-col gap-5 justify-between w-4/12'>
          <div className='relative h-3/5 border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Groups</span>
            <div className='flex flex-col gap-3 mt-5 overflow-auto scrollbar'>
              {groups?.map((group) => {
                return(
                  <div key={group.id} className='flex justify-between border-b'>
                    <span>{group.name}</span>
                    <div>
                      <button className='text-info' onClick={() => handleEditeGroup(group)} ><PencilSquareIcon className='w-5'/></button>
                      <button onClick={() => handleDeleteGroup(group.id)} className='text-error'><TrashIcon className='w-5'/></button>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
          <div className='flex flex-wrap gap-5 h-2/5 border rounded-lg p-5 bg-base-200'>
            
          
          </div>
          <div className='flex gap-5'>
              <button onClick={() => (document.getElementById('createuser')).showModal()} className="btnd bg-success w-28">Create User</button>
              <button onClick={() => (document.getElementById('creategroup')).showModal()} className="btnd bg-accent w-40">Create Group</button>
            </div>
        </div>

      </div>

      <dialog id="creategroup" className="modal">
        <div className="modal-box w-full max-w-xl bg-base-100">
          <div className="flex flex-col gap-5 relative border rounded-lg p-5">
              <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Create Group</span>
              <div className='flex gap-3 justify-between mt-5'>
                <input type='text' onChange={(e) => setGroupData({ ...groupData, name: e.target.value })} placeholder='Group Name' className='w-full'/>
                <input type='text' onChange={(e) => setGroupData({ ...groupData, description: e.target.value })} placeholder='description' className='w-full'/>
              </div>
              <div className='flex gap-5'>
                <form method="dialog" className="flex flex-col gap-5">
                  <button className="btnd w-20 bg-base-200">Close</button>
                </form>
                <button onClick={handleCreateGroup} className="btnd w-20 bg-success">Submit</button>
              </div>
          </div>
        </div>
      </dialog>     

      <dialog id="createuser" className="modal">
        <div className="modal-box w-full max-w-xl bg-base-100">
          <div className="flex flex-col gap-5 relative border rounded-lg p-5">
              <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Create User</span>
              <div className='flex flex-col gap-3 justify-between mt-5'>
                <input type='text' placeholder='Group Name' className='w-full'/>
                <input type='text' placeholder='description' className='w-full'/>
                 <select className='w-56' >
                  {groups?.map((gr)=>{ return <option key={gr.id} value={gr.id}>{gr.name}</option>})}
                </select>
              </div>
              <div className='flex gap-5'>
                <form method="dialog" className="flex flex-col gap-5">
                  <button className="btnd w-20 bg-base-200">Close</button>
                </form>
                <button onClick={handleCreateGroup} className="btnd w-20 bg-success">Submit</button>
              </div>
          </div>
        </div>
      </dialog>   

       <dialog id="edituser" className="modal">
        <div className="modal-box w-full max-w-xl bg-base-100">
          <div className="flex flex-col gap-5 relative border rounded-lg p-5">
              <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Edite User</span>
              <div className='flex flex-col gap-3 justify-between mt-5'>
                <input onChange={(e) => setEditUser(prev => ({...prev, name: e.target.value}))} value={edituser?.name} type='text' placeholder='Name' className='w-full'/>
                <input onChange={(e) => setEditUser(prev => ({...prev, email: e.target.value}))} value={edituser?.email} type='text' placeholder='Email' className='w-full'/>
                 <select value={edituser.groupId} onChange={(e) => setEditUser(prev => ({...prev, groupId: e.target.value}))} className='w-56' >
                  {groups?.map((gr)=>{ return <option key={gr.id} value={gr.id}>{gr.name}</option>})}
                </select>
              </div>
              <div className='flex gap-5'>
                <form method="dialog" className="flex flex-col gap-5">
                  <button className="btnd w-20 bg-base-200">Close</button>
                </form>
                <button onClick={handleUpdateUser} className="btnd w-20 bg-success">Submit</button>
              </div>
          </div>
        </div>
      </dialog>     

      <dialog id="editgroup" className="modal">
        <div className="w-[50%] bg-base-100 rounded-lg p-5">
          <div className="flex flex-col gap-5 relative border rounded-lg p-5">
              <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>{editGroup?.name}</span>
              <div className='flex flex-col gap-3 justify-between mt-5'>
                <div className='flex gap-5 mb-5'>
                  <input onChange={(e) => setEditGroup(prev => ({...prev, name: e.target.value}))} value={editGroup?.name} type='text' placeholder='Group Name' className='w-full'/>
                  <input onChange={(e) => setEditGroup(prev => ({...prev, name: e.target.value}))} value={editGroup?.description} type='text' placeholder='description' className='w-full'/>
                </div>
                <div className='flex gap-10 flex-wrap overflow-y-scroll h-[500px]'>
                  {editGroup?.permissions?.map((item) => {
                    return (
                      <div key={item.id} className='flex flex-col gap-3 w-60 h-20 bg-base-200 p-2 rounded-lg'>
                        <span>{item?.module.name}</span>
                        <div className='flex gap-2 items-center'>
                          <span>Access</span>
                          <input
                            type="checkbox"
                            checked={item.access === 1}
                            onChange={(e) => {
                              const updatedPermissions = editGroup.permissions.map(p =>
                                p.id === item.id ? { ...p, access: e.target.checked ? 1 : 0 } : p
                              );
                              setEditGroup(prev => ({ ...prev, permissions: updatedPermissions }));
                            }}
                            className="toggle border-success bg-success checked:border-error checked:bg-error checked:text-error"
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
              <div className='flex gap-5'>
                <form method="dialog" className="flex flex-col gap-5">
                  <button className="btnd w-20 bg-base-200">Close</button>
                </form>
                <button onClick={handleUpdate} className="btnd w-20 bg-success">Submit</button>
              </div>
          </div>
        </div>
      </dialog>       
    </>
  )
}

export default Users