import React, { useEffect, useState } from 'react'
import axios from 'axios';
import { TrashIcon, PencilSquareIcon, PlayCircleIcon, PlusCircleIcon} from '@heroicons/react/24/solid'


const MediaPlaylist = () => {

    const[mediaList, setMediaList] = useState([])
    const[error, setError] = useState('')
    const[video, setVideo] = useState('')
    const[play, setPlay] = useState({type:'', path:''})
    const[picture, setPicture] = useState('')
    const[data, setData] = useState({name:'', description:'', type:'', file:'', language:'', created_by:'1'})
    const [newplaylists, setNewPlaylists] = useState([])
    const [playlistName, setPlaylistName] = useState("")
    const [description, setDescription] = useState("")
    const [playlists, setPlaylists] = useState([])

    useEffect(() => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.get(`${baseUrl}/pidmedia`, { headers: { Authorization: `${token}`}}).then((response) => {
        setMediaList(response.data.data);
      })
      axios.get(`${baseUrl}/pid_playlist`, { headers: { Authorization: `${token}`}}).then((response) => {
        setPlaylists(response.data.data);
        console.log("playlists", playlists)
      })
    }, [])
 
    const addToList = (id) => {
      const newlist = mediaList?.find((x) => x.id === id);
      setNewPlaylists([newlist, ...newplaylists]);
    };

    const deleteFromList = (id) => {
      const updatedList = newplaylists?.filter((x) => x.id !== id);
      setNewPlaylists(updatedList);
    };

 
    useEffect(() => {
      console.log("playlists", playlists)
    }, [playlists])

    const playVideo = (item) => {
      console.log("playVideo", item)
      setPlay({...play, path:item.path, type:item.type})
    }


    const handleUpload= (event) => {
      setError('')
      const file = event.target.files[0]
      
      const allowedTypes = ['image/jpeg', 'video/mp4']
      
      if (file && !allowedTypes.includes(file.type)) {
        setError("Please select a valid file (.jpg, .jpeg, or .mp4)")
        event.target.value = ''
      }
      else{

        if(file.type === 'image/jpeg'){
          setPicture(event.target.files[0])
          setVideo('')
          setData({ ...data, type: 'image', file: event.target.files[0] })
        }
        else if(file.type === 'video/mp4'){
          setVideo(event.target.files[0])
          setPicture('')
          setData({ ...data, type: 'video', file: event.target.files[0] })
        }
      }
      
    }

    const submitUpload = () => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token = localStorage.getItem("authToken");
    
      const formData = new FormData()
      formData.append('file', data.file)
      formData.append('name', data.name)
      formData.append('description', data.description)
      formData.append('type', data.type)
      formData.append('language', data.language)
      formData.append('created_by', data.created_by)
    
      for (let [key, value] of formData.entries()) {
        console.log(`${key}:`, value);
      }

      axios.post(`${baseUrl}/mediaplayback/upload`, formData, {
          headers: {
            'Authorization': `${token}`,
            'Content-Type': 'multipart/form-data',
          }
        })
        .then((response) => {
          console.log("response", response);
          //setAudioList(response.data.data.sort((a, b) => b.id - a.id));
        })
        .catch((error) => {
          console.error("Upload error", error);
        });
    };
  
    const submitPlaylist = () => {
      const data = {
        name:playlistName,
        description:description,
        mediaplayback_id :newplaylists.filter((x) => x.id).map((x) => x.id)
      }
      console.log(data);
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.post(`${baseUrl}/pid_playlist`, data, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log(response);
        if(response.status === 201){
          setNewPlaylists([])
          setPlaylistName("")
          setDescription("")
          setPlay({path:'', type:''})
          setPlaylists(response.data.data)
        }
       
      });
    }

  return (
    <>
    <div className='flex h-full gap-10'>
      <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Media Playlist</span>
          <div className='flex flex-col mt-3 gap-2 overflow-auto scrollbar'>
               {playlists?.map((item, key) => {
                  return(
                    <div key={key} tabIndex={0} className="collapse rounded-md bg-base-200 mb-3">
                      <div className="flex justify-between text-md text-base-400 gap-5 collapse-title min-h-12 font-bold">
                        <span>{item.name}</span>
                        <div className='flex gap-2'>
                          <button className='text-info'><PencilSquareIcon className='w-5'/></button>
                          <button className='text-error'><TrashIcon className='w-5'/></button>
                        </div>
                      </div>
                      <div className="collapse-content">
                        <table className='w-full'>
                          <thead className='text-left bg-base-300 p-2 text-base-100'>
                            <tr className='border-b'>
                              <th>Name</th>
                              <th>Type</th>
                              <th>PID Text</th>
                              <th>Audio Location</th>
                            </tr>
                          </thead>
                          <tbody>
                          {item.media_list?.map((audio, ind) => {
                            return(
                            <tr key={ind} className='h-10'>
                              <td>{audio.name}</td>
                              <td>{audio.type}</td>
                              <td>{audio.description}</td>
                              <td>{audio.path}</td>
                            </tr>
                            )
                          })}
                          </tbody>
                        </table>
                        
                      </div>
                    </div>
                  )
                })}
          </div>
      </div>

      <div className='flex flex-col gap-5 justify-between w-4/12'>
        <div className='relative border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Medias</span>
          <div className='flex flex-col gap-3 mt-5 overflow-auto scrollbar h-[350px]'>
            {mediaList?.map((media) => {
              return(
                <div key={media.id} className='flex justify-between p-2 mb-2 bg-base-100 rounded-lg'>
                  <span>{media.name}</span>
                  <button onClick={() => addToList(media.id)} className='flex items-center justify-center bg-accent rounded-full w-6 h-6 text-2xl pb-1'>+</button>
                </div>
              )
            })

            }
          </div>
        </div>
        <div className='flex flex-wrap gap-5 h-2/5 border rounded-lg p-5 bg-base-200'>
          {newplaylists?.map((item, key) => {
            return(
              <div key={key} className='flex gap-5 justify-between h-10 p-2 mb-2 bg-base-100 rounded-lg'>
                <span>{item.name}</span>
                <button onClick={() => deleteFromList(item.id)} className='bg-error rounded-full w-6 h-6'>X</button>
              </div>
            )
          })}
        
        </div>
        <div className='flex gap-5'>
            <button onClick={() => (document.getElementById('createPlaylist')).showModal()} className="btnd bg-success w-28">Submit</button>
            <button onClick={() => (document.getElementById('importMusic')).showModal()} className="btnd bg-accent w-40">Import New Media</button>
          </div>
      </div>

    </div>

    <dialog id="importMusic" className="modal">
      <div className="modal-box w-full max-w-xl bg-base-100">
        <div className="flex flex-col gap-5 relative border rounded-lg p-5">
            <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Import <span className='text-warning ml-3'>mp4 - jpg</span></span>
            <div className='flex justify-between mt-5'>
              <input type='text' onChange={(e) => setData({ ...data, name: e.target.value })} placeholder='Name' className='w-56'/>
              <select onChange={(e) => setData({ ...data, language: e.target.value })} className='w-56' >
                  <option value='English'>English</option>
                  <option value='Malayi'>Malayi</option>
                  <option value='Mandarin'>Mandarin</option>
                  <option value='Hindi'>Hindi</option>
                </select>
            </div>
            <input type='text' onChange={(e) => setData({ ...data, description: e.target.value })} placeholder='Description' />
            <input type="file" onChange={handleUpload} className="file-input file-input-bordered w-full max-w-xs" accept=".mp4"/>
            <div className='w-full min-h-[300px] bg-black'>
              {video && <video controls className='w-full h-[300px]' src={video && URL.createObjectURL(video)} poster='' />}
              {picture && <img className='w-full h-[300px]' src={picture && URL.createObjectURL(picture)} />}
            </div>
            {error != '' && <span className='text-error'>{error}</span>}
            <div className='flex gap-5'>
              <form method="dialog" className="flex flex-col gap-5">
                <button className="btnd w-20 bg-base-200">Close</button>
              </form>
              <button onClick={submitUpload} className="btnd w-20 bg-success">Submit</button>
            </div>
        </div>
      </div>
    </dialog>

    <dialog id="createPlaylist" className="modal">
        <div className="modal-box w-11/12 max-w-2xl bg-base-100">
          <div className="relative border rounded-lg p-5">
          <span className='absolute left-8 bg-base-300 text-base-100 rounded-lg px-5' style={{top:-15}}>New Media Playlist</span>
            <div className="flex flex-col gap-5 mt-5">
              <input onChange={(e) => setPlaylistName(e.target.value)} type='text' placeholder='Playlist Name' />
              <input onChange={(e) => setDescription(e.target.value)} type='text' placeholder='Description' />
              {newplaylists?.map((item) => {
                return(
                  <div key={item.id} className='flex justify-between'>
                    <div className='flex gap-3 items-center'>
                      <span>{item.name}</span>
                      <PlayCircleIcon onClick={() => playVideo(item)} className='w-5 mt-2'/>
                    </div>
                    <span>{item.duration}</span>
                  </div>
                )
              })}
              <div className='flex gap-5 modal-action'>
                <div className='flex flex-1 gap-2'>
                  {/* <span className='text-warning'>Total Duration :</span> */}
                  {/* <span className='text-pink-500 font-bold'>{convertSecondsToTime(duration)}</span> */}
                </div>
                <form method="dialog" className="flex gap-5">
                  <button className="btnd w-20 bg-base-200">Close</button>
                  <button onClick={() => submitPlaylist()} className="btnd w-20 bg-success">Submit</button> 
                </form>
              </div>
              </div>
              {
                play.type === 'VIDEO' ? 
                  <video controls className='w-full h-[360px] mt-5' src={`${process.env.REACT_APP_VIDEO_URL}/${play.path}`} poster='' />
              :
                play.type == "IMAGE" ?
                <img className='w-full h-[360px] mt-5' src={`${process.env.REACT_APP_PICTURE_URL}/${play.path}`} />
              : ""  
            }
          </div>
        </div>
      </dialog>
    
    </>
  )
}

export default MediaPlaylist