import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon, InformationCircleIcon } from '@heroicons/react/24/solid'
import { DataGrid } from '@mui/x-data-grid';
import { CirclePicker } from 'react-color'
import axios from 'axios';

const AlarmPriority = () => {

  const [priorities, setPriorities] = useState([])
  const [edit, setEdit] = useState({})
  const [show, setShow] = useState(false)
  const colors = ["#3f51b5","#2196f3","#a30000ff","#D5090E","#19530dff","#3fa165ff", "#894affff", "#531db6ff"]


  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.get(`${baseUrl}/alarm-severity`, { headers: { Authorization: `${token}`}}).then((response) => {
       
      console.log('priorities', response.data.data)
        setPriorities(response.data.data)
    })
  }, [])


  const columns = [
   
    { field: 'description', headerName: 'Name', flex:1  },
    { field: 'priority', headerName: 'Priority', width: 100},
    { field: 'color', headerName: 'Color', width: 100,
      renderCell: (params) => {
        return(
          <div className='h-6 w-10 mt-3' style={{backgroundColor:`${params.row.color}`}} />
        )
      }
    },
    { field: 'action', headerName: 'Actions', width: 100 ,  
      renderCell: (params) => {
        return(
          <div className='flex gap-2 justify-center items-center h-12'>
            <PencilSquareIcon onClick={() => handleEdit(params.row)} className='w-5 text-info'/>
          </div>
        )
      }}
  ]

  const handleChangeColor = (hex) => {
    console.log("hex", hex)
    setEdit((prevState) => ({...prevState, color: hex}))
    setShow(false)
  }

   const handleEdit = (row) => {
    setEdit(row)
    document.getElementById('edite').showModal()
  }

  const submit = () => {
    console.log("Edite request", edit)
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.put(`${baseUrl}/alarm-severity/${edit.id}`, edit, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Responce edite", response.data)
      setPriorities(response.data.data)
    })

  }

  return (
      <div className='relative border h-[77vh] bg-base-200 rounded-lg p-5'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>PA Alarms</span>
        <DataGrid rows={priorities} columns={columns} sx={{ border: 0 }} initialState={{...priorities.initialState, pagination: { paginationModel: { pageSize: 10 } }}} />
    
        <dialog id="edite" className="modal">
          <div className="modal-box w-11/12 max-w-2xl bg-base-100">
            <div className="relative flex flex-col gap-5 border rounded-lg p-5 pt-10">
              <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Edite priority</span>
              <input onChange={(e) => setEdit((prevState) => ({...prevState, name: e.target.value}))} value={edit.name} type='text' placeholder='Playlist Name' className='input bg-base-100'/>
              <input onChange={(e) => setEdit((prevState) => ({...prevState, priority: e.target.value}))} value={edit.priority} type='text' placeholder='Playlist Name' className='input bg-base-100'/>
              <div className='relative flex gap-5 items-center my-5'>
                <span className='w-20'>Color</span>
                <button onClick={() => setShow(true)} className='btn btn-xs w-10 bg-black' style={{ backgroundColor:`${edit.color ? edit.color : "#FFF" }`}}/>
                <div className={`${!show && "hidden"} flex w-48 p-3 absolute bg-base-200`} style={{left:"0px", top:"30px", zIndex:100}}>
                  <CirclePicker colors={colors} onChangeComplete={(e) => handleChangeColor(e.hex)}  />
                </div>
              </div>
              <form method="dialog" className="flex flex-col gap-5">
                <div className='flex gap-5 modal-action'>
                  <button className="btnd w-20 bg-error">Close</button>
                  <button onClick={submit} className="btnd w-20 bg-success">Submit</button>
                </div>
              </form>
            </div>
          </div>
        </dialog>
      </div>
  )
}

export default AlarmPriority