import './App.css';
import {Routes, Route, useLocation } from 'react-router-dom'
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import Header from './components/header'
import ProtectedRoute from './protectedRoute'

import Stations from './screens/stations/index'
import Login from './screens/login/index'
import Dashboard from './screens/dashboard/index'

import MessagePlaylist from './screens/papids/messagePlaylist';
import PlaylistBuilder from './screens/papids/playlistBuilder';
import MediaPlaylist from './screens/pids/mediaPlaylist';
import PidList from './screens/pids/pidList';
import MediaSchedule from './screens/pids/mediaschedule';
import EventSchedule from './screens/pids/eventschedule';
import Themplate from './screens/pids/themplate';
import Mimic from './screens/pids/mimic';

import PaEventSchedule from './screens/pa/paEventSchedule';
import MusicPlaylist from './screens/pa/musicPlaylist';
import Palogs from './screens/log/palogs';
import Clients from './screens/ads/clients';
import AdsManagement from './screens/ads/adsManagement';
import PaAlarms from './screens/alarms/paAlarms';
import PidsAlarms from './screens/alarms/pidsAlarms';
import HistoryAlarms from './screens/alarms/historyAlarms';
import Users from './screens/config/users';
import UserGroups from './screens/config/usergroups';
import PaPriority from './screens/config/papriority';
import PidsPriority from './screens/config/pidspriority';
import AlarmPriority from './screens/config/alarmpriority';
import Help from './screens/config/help';
import Profile from './screens/pids/profile';
import MessageSchedule from './screens/papids/messageSchedule';
import MusicSchedule from './screens/pa/musicSchedule';



function App() {

  const location = useLocation()

  return (
    <LocalizationProvider dateAdapter={AdapterDayjs}>
        {location.pathname !== '/login' && location.pathname !== '/dashboard/iframe' && location.pathname !== '/iframe' && <Header />}
          <div className={`${location.pathname !== '/login' && "pt-44 h-full pl-24 pr-10"}`}>
            <Routes>
              <Route path="/" element={<ProtectedRoute element={<Stations />} />} />
              <Route path="/dashboard" element={<ProtectedRoute element={<><Dashboard /></>} />} />

              <Route path="/papids" element={<ProtectedRoute element={<><MessagePlaylist /></>} />} />
              <Route path="/papids/message-playlist" element={<ProtectedRoute element={<><MessagePlaylist /></>} />} />
              <Route path="/papids/message-playlist-builder" element={<ProtectedRoute element={<><PlaylistBuilder /></>} />} />
              <Route path="/papids/messageschedule" element={<ProtectedRoute element={<><MessageSchedule /></>} />} />



              <Route path="/pa" element={<ProtectedRoute element={<><PaEventSchedule /></>} />} />
              <Route path="/pa/eventschedule" element={<ProtectedRoute element={<><PaEventSchedule /></>} />} />
              <Route path="/pa/musicplaylist" element={<ProtectedRoute element={<><MusicPlaylist /></>} />} />
              <Route path="/pa/musicschedule" element={<ProtectedRoute element={<><MusicSchedule /></>} />} />

              <Route path="/pids" element={<ProtectedRoute element={<><PidList /></>} />} />
              <Route path="/pids/pidlist" element={<ProtectedRoute element={<><PidList /></>} />} />
              <Route path="/pids/mediaplaylist" element={<ProtectedRoute element={<><MediaPlaylist /></>} />} />
              <Route path="/pids/mediaschedule" element={<ProtectedRoute element={<><MediaSchedule /></>} />} />
              <Route path="/pids/eventschedule" element={<ProtectedRoute element={<><EventSchedule /></>} />} />
              <Route path="/pids/themplate" element={<ProtectedRoute element={<><Themplate /></>} />} />
              <Route path="/pids/pidsmimics" element={<ProtectedRoute element={<><Mimic /></>} />} />
              <Route path="/pids/profile" element={<ProtectedRoute element={<><Profile /></>} />} />



              <Route path="/ads" element={<ProtectedRoute element={<><AdsManagement /></>} />} />
              <Route path="/ads/adsmanagement" element={<ProtectedRoute element={<><AdsManagement /></>} />} />
              <Route path="/ads/clients" element={<ProtectedRoute element={<><Clients /></>} />} />

              <Route path="/alarm" element={<ProtectedRoute element={<><PaAlarms /></>} />} />
              <Route path="/alarm/paalarms" element={<ProtectedRoute element={<><PaAlarms /></>} />} />
              <Route path="/alarm/pidsalarms" element={<ProtectedRoute element={<><PidsAlarms /></>} />} />
              <Route path="/alarm/historyalarms" element={<ProtectedRoute element={<><HistoryAlarms /></>} />} />

              <Route path="/log" element={<ProtectedRoute element={<><Palogs /></>} />} />
              <Route path="/log/palog" element={<ProtectedRoute element={<><Palogs /></>} />} />

              <Route path="/config" element={<ProtectedRoute element={<><PaPriority /></>} />} />
              <Route path="/config/users" element={<ProtectedRoute element={<><Users /></>} />} />
              <Route path="/config/usergroups" element={<ProtectedRoute element={<><UserGroups /></>} />} />
              <Route path="/config/papriority" element={<ProtectedRoute element={<><PaPriority /></>} />} />
              <Route path="/config/pidspriority" element={<ProtectedRoute element={<><PidsPriority /></>} />} />
              <Route path="/config/alarmpriority" element={<ProtectedRoute element={<><AlarmPriority /></>} />} />
              <Route path="/config/help" element={<ProtectedRoute element={<><Help /></>} />} />
            


              <Route path="/login" element={<Login />} />

              <Route path="/iframe" element={<Stations />}  />     
              <Route path="/dashboard/iframe" element={<Dashboard />} />   
            </Routes>
          </div>
        {/* {location.pathname !== '/login' && <Sidebar />} */}
        </LocalizationProvider>
  );
}

export default App;