import React, { useEffect, useState, useMemo  } from 'react'
import { TrashIcon, PencilSquareIcon, InformationCircleIcon } from '@heroicons/react/24/solid'
import axios from 'axios'
import {useWebSocket} from '../../context/WebSocketContext'
import { DataGrid } from '@mui/x-data-grid';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs from 'dayjs';
import { TextField, Box } from '@mui/material';



const PaAlarms = () => {

  const [alarms, setAlarms] = useState([])
  const [fromDate, setFromDate] = useState(null)
  const [toDate, setToDate] = useState(null);
  const [searchText, setSearchText] = useState('')
  const { alarmsMessage } = useWebSocket()


  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.get(`${baseUrl}/alarm?key=pa`, { headers: { Authorization: `${token}`}}).then((response) => {
       
      console.log('Alarms', response.data.data)
        setAlarms(response.data.data)
    })
  }, [alarmsMessage])

  const filteredRows = useMemo(() => {
    return alarms.filter((row) => {
      const matchesSearch = row.name.toLowerCase().includes(searchText.toLowerCase())
      const rowDate = dayjs(row.createdOn)
      const afterFrom = fromDate ? rowDate.isAfter(dayjs(fromDate).subtract(1, 'day')) : true
      const beforeTo = toDate ? rowDate.isBefore(dayjs(toDate).add(1, 'day')) : true
      return matchesSearch && afterFrom && beforeTo
    });
  }, [searchText, fromDate, toDate])

  

  const columns = [
    { field: 'severity', headerName: 'Severity', width: 100, renderCell: (params) => {
      return(
        <div className={`${params.row.severity == 1 ? "bg-error" : params.row.severity == 2 ? "bg-warning" : params.row.severity == 3 ? "bg-warning-content" : "bg-success" }
          flex items-center justify-center font-bold text-lg rounded-full w-7 h-7 mt-3`}>!</div>
        
      )
    }},
    { field: 'name', headerName: 'Name', flex:1  },
    { field: 'createdOn', headerName: 'Create On', width: 250 },
    { field: 'description', headerName: 'Fault', width: 150 },
    { field: 'action', headerName: 'Actions', width: 100 ,  
      renderCell: (params) => {
        return(
          <div className='flex gap-2 justify-center items-center h-12'>
            <PencilSquareIcon  className='w-5 text-info'/>
            <TrashIcon  className='w-5 text-error'/>
          </div>
        )
      }},
  ];

  // useEffect(() => {
  //   console.log("Allarm Status", alarmsMessage)

  // }, [alarmsMessage]);

  return (
    <div className='relative border h-[77vh] bg-base-200 rounded-lg p-5'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>PA Alarms</span>
        <div className='flex gap-10 h-12 z-10 mb-5' style={{top:-20}} >
          <TextField label="Search by name" variant="outlined" value={searchText} onChange={(e) => setSearchText(e.target.value)}/>
          <DatePicker label="From" value={fromDate} onChange={(date) => setFromDate(date)} />
          <DatePicker label="To" value={toDate} onChange={(date) => setToDate(date)} />
        </div>

        <DataGrid rows={alarms} columns={columns} sx={{ border: 0 }} initialState={{...alarms.initialState, pagination: { paginationModel: { pageSize: 10 } }}} />
    </div>
  )
}

export default PaAlarms