import React from 'react'

const StepSix =  ({handleBack, handleNext, step, handleSubmit, uploaded, loading, data}) => {


  return (
    <>
    <div className='flex flex-col justify-between w-full items-center'>
    <div className='flex flex-col flex-1 gap-5 w-full h-full justify-center items-center'>
      <div className='flex flex-col items-center'>
        <span className='mb-3 text-2xl'>Over view details</span>
        <small>Thisis full details</small>
      </div>
      <div className='flex flex-col gap-5 w-full justify-center items-center'>
        <div className='rounded-lg bg-accent px-4 py-2'>
            Audio Name : <span className='font-bold text-base-100'>{data.audioName}</span>
        </div>
        <table className='w-8/12 border-separate border-spacing-2' >
          <tbody>
            <tr>
              <td className='w-40'>BM recording</td>
              <td className='flex-1'>
                <audio controls className="" style={{ height: '40px', width:"350px" }}>
                  <source src={data.audioBM} type="audio/mpeg" />
                  Your browser does not support the audio element.
                </audio>
              </td>
              <td className='w-40'>En recording</td>
              <td className='flex-1'>
                <audio controls className="" style={{ height: '40px', width:"350px" }}>
                  <source src={data.audioEN} type="audio/mpeg" />
                  Your browser does not support the audio element.
                </audio>
              </td>
            </tr>
            <tr>
              <td>BM pid text</td>
              <td className='bg-base-100 p-2 rounded-xl'>{data.textBM}</td>
              <td>EN pid text</td>
              <td className='bg-base-100 p-2 rounded-xl'>{data.textEN}</td>
            </tr>
            <tr>
              <td>MA recording</td>
              <td>
                <audio controls className="" style={{ height: '40px', width:"350px" }}>
                  <source src={data.audioMA} type="audio/mpeg" />
                  Your browser does not support the audio element.
                </audio>
              </td>
              <td>HI recording</td>
              <td>
                <audio controls className="" style={{ height: '40px', width:"350px" }}>
                  <source src={data.audioHI} type="audio/mpeg" />
                  Your browser does not support the audio element.
                </audio>
              </td>
            </tr>
            <tr>
              <td>MA pid text</td>
              <td className='bg-base-100 p-2 rounded-xl'>{data.textMA}</td>
              <td>HI pid text</td>
              <td className='bg-base-100 p-2 rounded-xl'>{data.textHI}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
    <div className='flex gap-5'>
      <button onClick={() => handleBack(step)} className='w-20 btn btn-sm btn-info'>Back</button>
      {!uploaded ? 
        <button onClick={() => handleSubmit(step)} className='w-20 btn btn-sm btn-info' >Submit</button> 
      :
      <button onClick={() => handleNext(step)} className='w-20 btn btn-sm btn-info' disabled={!uploaded} >Next</button>}
    </div>
  </div>
  <dialog id="loading" className={`modal ${loading && "modal-open"}`}>
    <div className="modal-box flex justify-center items-center">
      <span className='mr-5 text-xl'>Loading</span>
      <span className="loading loading-dots loading-lg"></span>
    </div>
  </dialog>
  </>
  )
}

export default StepSix