import React, { useEffect, useState } from 'react'
import axios from 'axios';
import Toast from '../../components/toast';
import { TrashIcon, PencilSquareIcon, ArrowDownIcon} from '@heroicons/react/24/solid'



const MusicSchedule = () => {
  const [schedules, setSchedules] = useState([])
  const [editschedule, setEditeSchedule] = useState({})
  const [newplaylists, setNewPlaylists] = useState([]);
  const [highlightedId, setHighlightedId] = useState(null)
  const [playlists, setPlaylists] = useState([])
  const [editmusics, setEditMusics] = useState({})
  const [openIndex, setOpenIndex] = useState(null)
  const [newschedule, setNewschedule] = useState(
      { 
        name:"",
        type:"Daily",
        description:"",
        start_date:"", 
        end_date:"", 
        start_time:"", 
        end_time:"", 
        monday:0,
        tuesday:0,
        wednesday:0,
        thursday:0,
        friday:0,
        saturday:0,
        sunday:0,
        playlist_id:0, 
        is_active: 0 
      }
    )
  
  useEffect(() => {
    console.log("editschedule", editschedule);
   
  }, [editschedule])


  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/musicschedule`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("musicschedule", response.data);
      setSchedules(response.data.data);
    })
    axios.get(`${baseUrl}/musicplaylist`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Playlist", response.data);
      setPlaylists(response.data.data);
    })
  }, [])
  

  const handleHighlight = (id) => {
    setHighlightedId(id);
    setTimeout(() => {
      setHighlightedId(null);
    }, 4000);
  }

  const toggleOpen = (item) => {
    console.log("Sch id:", item)
    setOpenIndex(openIndex === item.id ? null : item.id)
    setEditeSchedule(item)
  }

  const handleStatus =(sch) => {
    const updatedItem = {...sch, is_active: !sch.is_active}
    sch.is_active = !sch.is_active

    console.log("sch", sch);

    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/musicschedule/${sch.id}`, updatedItem, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log( response.data);
      
    })
  }


  const updateSch =() =>{
    console.log("Start update ...")
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/musicschedule/${editschedule.id}`, editschedule, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Update responce", response.data.data);
        handleHighlight(editschedule.id)
  })
  }

  const createSch =() =>{
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/musicschedule`, newschedule, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("new musicschedule", response.data);
      setSchedules(response.data.data);
    })
  }

  const deleteSch =(id) =>{
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.delete(`${baseUrl}/musicschedule/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Delete schedule", response)
      if(response.status == 200){
        setSchedules((prev) => prev.filter((schedule) => schedule.id !== id))
      }
      
    })
  }

  return (
    <div className='flex h-full gap-10'>

      <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Schedules List</span>
         {schedules?.map((item) => {
            return(
              <div key={item.id} className='flex flex-col mb-3'>
                <div className={`flex items-center justify-between h-10 rounded-md ${ highlightedId === item.id ? 'blink-green' : 'bg-base-200'} px-3`}>
                  <span>{item.name}</span>
                  <div className='flex gap-2 items-center'>
                     <input type="checkbox" defaultChecked={item.is_active} onChange={() => handleStatus(item)} className="toggle toggle-md h-5 toggle-success" />
                    <button onClick={() => toggleOpen(item)} className='text-info' >
                      <PencilSquareIcon className='w-5'/></button>
                    <button onClick={() => deleteSch(item.id)} className='text-error'><TrashIcon className='w-5'/></button>
                  </div>
                </div>
                <div className={`${openIndex === item.id ? 'h-80' : 'h-0'} relative border-t-4 bg-slate-200 overflow-hidden transition-all duration-500 ease-in-out`}>
                  <div className='flex'>
                    <div className='flex flex-col gap-5 p-5'>
                      <div className='flex gap-10 mb-5'>
                        <div className='flex items-center gap-2'>
                            <span>Schedule Name: </span>
                            <input onChange={(x) => setEditeSchedule(prev => ({...prev, name: x.target.value}))} value={editschedule?.name} name='name' type="text"  autoFocus />
                        </div>
                        <div className='flex items-center gap-2'>
                            <span>Description: </span>
                            <input onChange={(x) => setEditeSchedule(prev => ({...prev, description: x.target.value}))} value={editschedule?.description} name='description' type="text"  autoFocus />
                        </div>
                        <div className='flex items-center gap-2'>
                          <span className='w-2/5'>Playlist</span>
                          <select type='text' onChange={(x) => setEditeSchedule(prev => ({...prev, playlist_id: Number(x.target.value)}))} value={editschedule?.playlist_id?.toString()} className='min-w-40'>
                            {playlists?.map((item) => {
                              return(
                                <option key={item.id} value={item?.id}>{item?.name}</option>
                              )
                            })}
                          </select>
                        </div>
                      </div>

                      <div className='flex justify-between text-sm my-10'>
                        <div className='flex gap-2 items-center'> 
                          <span>Monday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, monday: x.target.checked ? 1 : 0}))}  type="checkbox" checked={editschedule?.monday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Tuesday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, tuesday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.tuesday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Wednesday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, wednesday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.wednesday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Thursday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, thursday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.thursday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Friday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, friday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.friday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Saturday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, saturday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.saturday === 1} className="checkbox" />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span>Sunday</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, sunday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.sunday === 1} className="checkbox" />
                        </div>
                          
                      </div>

                      <div className='flex flex-wrap gap-5 text-sm mb-5'>
                        <div className='flex gap-2 items-center'> 
                          <span className='w-20'>Start Date :</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, start_date: x.target.value}))} name='start_date' type="text" defaultValue={editschedule?.start_date} className='w-36' />
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span className='w-20'>End Date :</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, end_date: x.target.value}))} name='end_date' type="text" defaultValue={editschedule?.end_date} className='w-36'/>
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span className='w-20'>Start time :</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, start_time: x.target.value}))} name='start_time' type="text" defaultValue={editschedule?.start_time} className='w-36'/>
                        </div>
                        <div className='flex gap-2 items-center'> 
                          <span className='w-20'>End time :</span>
                          <input onChange={(x) => setEditeSchedule(prev => ({...prev, end_time: x.target.value}))} name='end_time' type="text" defaultValue={editschedule?.end_time} className='w-36'/>
                        </div>
                      </div>
                     
                    </div>

                    <button onClick={updateSch} className='absolute bottom-2 right-2 btn btn-success btn-xs text-base-100 px-5'>SAVE</button>
                  </div>
                </div>
              </div>
          )})}
      </div>

      <div className='flex flex-col gap-5 justify-between w-4/12'>
        
        <div className='relative h-full border rounded-lg p-5 bg-base-200'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Create Schedule</span>
             <div className='flex gap-5 items-center text-sm mb-10'>
             <span className='w-2/5'>Schedule Name</span>
              <input type='text' placeholder='Description' onChange={(x) => setNewschedule(prev => ({...prev, name: x.target.value}))} defaultValue={newschedule.name} className='w-full'/>
          </div>
          <div className='flex flex-col gap-3 my-5 text-sm'>
            <div className='flex gap-5 items-center'>
              <span className='w-2/5'>Playlist</span>
              <select type='text' onChange={(x) => setNewschedule(prev => ({...prev, playlist_id: x.target.value}))} value={newschedule?.playlist_id?.toString()} className='w-full'>
                <option key="null" value="">Select Playlist</option>
                {playlists?.map((item) => {
                  return(
                    <option key={item.id} value={item?.id}>{item?.name}</option>
                  )
                })}
              </select>
             
            </div>
          </div>
          <div className='flex gap-5 items-center text-sm mb-10'>
             <span className='w-2/5'>Description</span>
              <input type='text' placeholder='Description' onChange={(x) => setNewschedule(prev => ({...prev, description: x.target.value}))} defaultValue={newschedule.description} className='w-full'/>
          </div>

          <div className='flex gap-5 items-center text-sm mb-5'>
              <span className='w-5/12'>Start date</span>
              <input type='text' placeholder='Start date' onChange={(x) => setNewschedule(prev => ({...prev, start_date: x.target.value}))} defaultValue={newschedule.start_date} className='w-full'/>
              <span className='w-5/12'>End date</span>
              <input type='text' placeholder='End date' onChange={(x) => setNewschedule(prev => ({...prev, end_date: x.target.value}))} defaultValue={newschedule.end_date} className='w-full'/>
          </div>

          <div className='flex gap-5 items-center text-sm'>
              <span className='w-5/12'>Start time</span>
              <input type='text' placeholder='Start time (HH:mm)' onChange={(x) => setNewschedule(prev => ({...prev, start_time: x.target.value}))} defaultValue={newschedule.start_time} className='w-full'/>
              <span className='w-5/12'>End time</span>
              <input type='text' placeholder='End time (HH:mm)' onChange={(x) => setNewschedule(prev => ({...prev, end_time: x.target.value}))} defaultValue={newschedule.end_time} className='w-full'/>
          </div>

          <div className='flex justify-between bg-base-100 rounded-md p-2 my-10 text-sm'>
            <div className='flex flex-col'>
              <span className=''>Mon</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, monday: x.target.checked ? 1 : 0}))} checked={newschedule.monday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Tue</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, tuesday: x.target.checked ? 1 : 0}))} checked={newschedule.tuesday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Wen</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, wednesday: x.target.checked ? 1 : 0}))} checked={newschedule.wednesday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Tue</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, thursday: x.target.checked ? 1 : 0}))}  checked={newschedule.thursday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Fri</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, friday: x.target.checked ? 1 : 0}))} checked={newschedule.friday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Sat</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, saturday: x.target.checked ? 1 : 0}))} checked={newschedule.saturday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Sun</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, sunday: x.target.checked ? 1 : 0}))} checked={newschedule.sunday === 1}/>
            </div>
          </div>

          <div className='flex flex-col bg-base-100 rounded-md'>

          </div>
        </div>

        <div className='flex gap-5'>
            <button onClick={createSch} className="btnd bg-success w-28">Create</button>
        </div>
      </div>


    </div>
  )
}

export default MusicSchedule