import React, { useEffect, useState } from 'react'

const AlertMessage = ({message, type}) => {

    const [bg, setBg] = useState('')
    const [status, setStatus] = useState(false)

    useEffect(() => {
        reload()
    }, [type]) // Depend on 'type' so it triggers whenever it changes

    const reload = () => {

        // Set the background color based on 'type'
        if(type === 'success') {
            setBg('#347928') // Success color (green)
        } else if(type === 'error') {
            setBg('#f44336') // Error color (red)
        } 

        // Display the alert message
        setStatus(true)

        // Hide after the provided time duration
        setTimeout(() => {
            setStatus(false)
        }, 3000)
    }

    return (
        <div className='fixed flex justify-center items-center text-white top-0 left-0 w-full h-auto z-10 p-10' style={{backgroundColor: bg, transition: 'background-color 0.5s ease-in-out'}}>
            {status && message}
        </div>
    )
}

export default AlertMessage
