import { motion } from 'framer-motion';
import {ExclamationCircleIcon} from '@heroicons/react/24/solid'
import { useEffect, useState } from 'react';
import axios from 'axios';


const LatestAlarms = ({ title}) => {
  const [alarms, setAlarms] = useState([]);

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token = localStorage.getItem("authToken");
    axios.get(`${baseUrl}/alarm?key=pa`, { headers: { Authorization: `${token}`}}).then((response) => {
      setAlarms(response.data.data.sort((a, b) => b.id - a.id).slice(0, 4));
    });
  }, [])
  return (
    <motion.div className="relative w-full border px-5 py-10 rounded-lg min-h-64 bg-base-200">
      <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>{title}</span>
        {alarms?.map((item, ind) => {
            return(
                <div key={ind} className='flex justify-between p-2 border-t'>
                    <span className='w-40'>{item.name}</span>
                    <span>{item.description}</span>
                    <span><ExclamationCircleIcon className='w-7 text-error'/></span>
                </div>
            )
        })}
    </motion.div>
  )
}

export default LatestAlarms