class JwtUtils {
    // Decodes a JWT token and returns the payload as an object
    static decodeToken(token) {
      if (!token) {
        console.error("No token provided");
        return null;
      }
      try {
        const payload = token.split('.')[1]; // Get the payload (second part of JWT)
        const decodedPayload = JSON.parse(atob(payload)); // Decode and parse the payload
        return decodedPayload; // Return the decoded payload
      } catch (error) {
        console.error("Error decoding the token:", error);
        return null;
      }
    }
  
    // Validates if the token is still valid (not expired)
    static isTokenValid(token) {
      if (!token) return false;
      try {
        const decoded = this.decodeToken(token);
        if (!decoded || !decoded.exp) return false; // If no exp claim is present, treat it as invalid
        const expiryTime = decoded.exp * 1000; // exp is in seconds, so convert it to milliseconds
        return expiryTime > Date.now(); // Check if the token has expired
      } catch (error) {
        return false; // If the token is invalid (corrupt or expired), return false
      }
    }
  
    // Retrieves the email from a decoded JWT token
    static getEmailFromToken(token) {
      const decoded = this.decodeToken(token);
      return decoded ? decoded.email : null; // Return the email if it exists in the decoded token
    }
  
    // Optionally, you can add more methods to retrieve other claims or information from the token
    static getNameFromToken(token) {
      const decoded = this.decodeToken(token);
      return decoded ? decoded.name : null; // Retrieve username if available in token
    }
  }
  
  export default JwtUtils;
  