import React, { useEffect, useState } from 'react'
import { DataGrid, GridColDef } from '@mui/x-data-grid';
import { TrashIcon, PencilSquareIcon} from '@heroicons/react/24/solid'
import axios from 'axios';

const PAEventSchedule = () => {
  
  const [highlightedId, setHighlightedId] = useState(null)
  const [schedules, setSchedules] = useState([])
  const [editschedule, setEditeSchedule] = useState({})
  const [locations, setLocations] = useState([])
  const [newschedule, setNewschedule] = useState(
    { 
      name:"",
      start_date:"", 
      end_date:"", 
      start_time:"", 
      end_time:"", 
      monday:0,
      tuesday:0,
      wednesday:0,
      thursday:0,
      friday:0,
      saturday:0,
      sunday:0,
      zones:[], 
      is_active: 0,
      priority:19,
      status:"1",
      type:1,
      activity:3
    }
  )


  const [openIndex, setOpenIndex] = useState(null)

  const toggleOpen = (item) => {
    console.log("Sch id:", item)
    setOpenIndex(openIndex === item.id ? null : item.id)
    setEditeSchedule(item)
  }

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/paeventschedule`, { headers: { Authorization: `${token}`}}).then((response) => {
      setSchedules(response.data.data);
    })
  
    axios.get(`${baseUrl}/getLocations`, { headers: { Authorization: `${token}`}}).then((resultLocation) => {
      setLocations(resultLocation.data)
    })
  
  }, [])

  const createSch =() =>{
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/paeventschedule`, newschedule, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("New sch responce", response.data.data);
        response.data.data.slice().sort((a, b) => b.id - a.id)
        setSchedules(response.data.data)
    });

  }


 const handleHighlight = (id) => {
    setHighlightedId(id);
    setTimeout(() => {
      setHighlightedId(null);
    }, 4000);
  }

  const editZones = (id) => {
    console.log(id)
      setEditeSchedule(prev => {
        const isPresent = prev.zones.includes(id)
        return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
      })
  }

  const updateSch =() =>{
    console.log("Start update ...")
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/paeventschedule/${editschedule.id}`, editschedule, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Update responce", response.data.data);
        response.data.data.slice().sort((a, b) => b.id - a.id)
        handleHighlight(editschedule.id)
    });

  }

   const updateZones = (id) => {
    console.log(id)
      setNewschedule(prev => {
        const isPresent = prev.zones.includes(id)
        return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
      })
  }



  const handleStatus =(sch) => {
    const updatedItem = {...sch, is_active: !sch.is_active}
    sch.is_active = !sch.is_active
    delete updatedItem.created_on
    delete updatedItem.updated_on
    delete updatedItem.deleted_on
    delete updatedItem.created_by

    console.log("sch", sch);

    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/paeventschedule/${sch.id}`, updatedItem, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log( response.data);
      
    });
  }

   const deleteEvent =(id) =>{
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.delete(`${baseUrl}/paeventschedule/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Delete Event schedule", response)
      if(response.status == 200){
        setSchedules((prev) => prev.filter((schedule) => schedule.id !== id))
      }
      
    })
  }
  
  useEffect(() => {
    console.log("newschedule", newschedule)
  
  }, [newschedule])

  return (
    <div className='flex h-full gap-10'>
      <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>PA Event Schedule</span>
          <div className='flex flex-col mt-3 gap-2 overflow-auto scrollbar'>
                {schedules?.map((item) => {
                    return(
                      <div key={item.id} className='flex flex-col mb-3'>
                        <div className={`flex items-center justify-between h-10 rounded-md ${ highlightedId === item.id ? 'blink-green' : 'bg-base-200'} px-3`}>
                          <span>{item.name}</span>
                          <div className='flex gap-2 items-center'>
                            <input type="checkbox" defaultChecked={item.is_active} onChange={() => handleStatus(item)} className="toggle toggle-md h-5 toggle-success" />
                            <button onClick={() => toggleOpen(item)} className='text-info' >
                            <PencilSquareIcon className='w-5'/></button>
                            <button onClick={() => deleteEvent(item.id)} className='text-error'><TrashIcon className='w-5'/></button>
                          </div>
                        </div>
                        <div className={`${openIndex === item.id ? 'h-full' : 'h-0'} relative border-t-4 bg-slate-200 overflow-hidden transition-all duration-500 ease-in-out`}>
                          <div className='flex flex-col gap-5 p-5'>
                              <div className='flex gap-10 mb-5'>
                                <div className='flex items-center gap-2'>
                                    <span>Schedule Name: </span>
                                    <input onChange={(x) => setEditeSchedule(prev => ({...prev, name: x.target.value}))} value={editschedule?.name} name='name' type="text"  autoFocus />
                                </div>
                                <div className='flex items-center gap-2'>
                                    <span>Description: </span>
                                    <input onChange={(x) => setEditeSchedule(prev => ({...prev, description: x.target.value}))} value={editschedule?.description} name='description' type="text"  autoFocus />
                                </div>
                                <div className='flex items-center gap-2'>
                                    <span>Interval: </span>
                                    <input onChange={(x) => setEditeSchedule(prev => ({...prev, interval: x.target.value}))} value={editschedule?.interval} name='interval' type="text" autoFocus />
                                </div>
                              </div>
                              <div className='flex gap-10 mb-5'>
                                <div className='flex items-center gap-2'>
                                    <span className='w-2/5'>Activity</span>
                                    <select type='text' onChange={(x) => setEditeSchedule(prev => ({...prev, type: x.target.value}))} value={editschedule?.type?.toString()} className='input input-sm w-3/5'>
                                      <option value='1'>Mute On</option>
                                      <option value='2'>Mute Off</option>
                                      <option value='3'>Night Volume On</option>
                                      <option value='4'>Night Volume Off</option>
                                    </select>
                                </div>
                                
                              </div>
                              <div className='flex gap-5 text-sm mb-5'>
                                <div className='flex gap-2 items-center'> 
                                  <span>Monday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, monday: x.target.checked ? 1 : 0}))}  type="checkbox" checked={editschedule?.monday === 1} className="checkbox" />
                                </div>
                                  <div className='flex gap-2 items-center'> 
                                  <span>Tuesday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, tuesday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.tuesday === 1} className="checkbox" />
                                </div>
                                  <div className='flex gap-2 items-center'> 
                                  <span>Wednesday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, wednesday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.wednesday === 1} className="checkbox" />
                                </div>
                                  <div className='flex gap-2 items-center'> 
                                  <span>Thursday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, thursday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.thursday === 1} className="checkbox" />
                                </div>
                                  <div className='flex gap-2 items-center'> 
                                  <span>Friday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, friday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.friday === 1} className="checkbox" />
                                </div>
                                  <div className='flex gap-2 items-center'> 
                                  <span>Saturday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, saturday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.saturday === 1} className="checkbox" />
                                </div>
                                <div className='flex gap-2 items-center'> 
                                  <span>Sunday :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, sunday: x.target.checked ? 1 : 0}))} type="checkbox" checked={editschedule?.sunday === 1} className="checkbox" />
                                </div>
                                  
                              </div>
                              <div className='flex gap-5 text-sm'>
                                <div className='flex gap-2 items-center'> 
                                  <span className='w-20'>Start Date :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, start_date: x.target.value}))} name='start_date' type="text" defaultValue={editschedule?.start_date} />
                                </div>
                                <div className='flex gap-2 items-center'> 
                                  <span className='w-20'>End Date :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, end_date: x.target.value}))} name='end_date' type="text" defaultValue={editschedule?.end_date}/>
                                </div>
                                </div>
                                  <div className='flex gap-5 text-sm'>
                                <div className='flex gap-2 items-center'> 
                                  <span className='w-20'>Start time :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, start_time: x.target.value}))} name='start_time' type="text" defaultValue={editschedule?.start_time}/>
                                </div>
                                <div className='flex gap-2 items-center'> 
                                  <span className='w-20'>End time :</span>
                                  <input onChange={(x) => setEditeSchedule(prev => ({...prev, end_time: x.target.value}))} name='end_time' type="text" defaultValue={editschedule?.end_time}/>
                                </div>
                              </div>
                                <div className='flex flex-col gap-5 text-sm'>
                                    <div className='w-6/12'>
                                      {locations?.map((loc) => {
                                      return(
                                        <div key={loc.id} className='flex gap-5 items-center p-2'>
                                          <span>{loc.location_name}</span>
                                          <div className='flex gap-3 wraper'>
                                            {loc.zones?.map((item) => {
                                              const isChecked = editschedule?.zones?.includes(item.id) ?? false;
                                              return(
                                                <div key={item.id} className='flex flex-col justify-center'>
                                                  <span>{item.zone}</span>
                                                  <input onChange={() => editZones(item.id)} checked={isChecked} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                                                </div>
                                              )
                                            })}
                                          </div>
                                        </div>
                                      )
                                    })}
                                    </div>
                                  </div>
                          </div>
                          <button onClick={updateSch} className='absolute bottom-2 right-2 btn btn-success btn-xs text-base-100'>SAVE</button>
                        </div>
                    </div>
                      
                    )
                  })
                }
          </div>
      </div>

      <div className='flex flex-col gap-5 justify-between w-4/12'>
        
        <div className='relative h-full border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Create Schedule</span>
          <div className='flex gap-5 items-center'>
            <span className='w-3/12'>Event name</span>
            <input type='text' placeholder='Start Date' onChange={(x) => setNewschedule(prev => ({...prev, name: x.target.value}))} defaultValue={newschedule.name} className='input input-sm w-3/5'/>
       <span className='w-3/12'>Description</span>
            <input type='text' placeholder='Start Date' onChange={(x) => setNewschedule(prev => ({...prev, description: x.target.value}))} defaultValue={newschedule.description} className='input input-sm w-3/5'/>
          </div>
         
          <div className='flex flex-col gap-3 my-5 overflow-auto scrollbar text-sm'>
            <div className='flex gap-5 items-center mb-5'>
              <span className='w-2/5'>Schedule</span>
              <select type='text' onChange={(x) => setNewschedule(prev => ({...prev, type: Number(x.target.value)}))} value={newschedule?.type?.toString()} className='input input-sm w-3/5'>
                <option value='1'>Mute On</option>
                <option value='2'>Mute Off</option>
                <option value='3'>Night Volume On</option>
                <option value='4'>Night Volume Off</option>
              </select>
              <span className='w-2/5'>Interval</span>
              <input type='text' placeholder='Interval' onChange={(x) => setNewschedule(prev => ({...prev, interval: Number(x.target.value)}))} defaultValue={newschedule.interval} className='input input-sm w-3/5'/>
            </div>
          </div>

          <div className='flex gap-5 items-center'>
              <span className='w-3/12'>Start Date</span>
              <input type='text' placeholder='Start Date' onChange={(x) => setNewschedule(prev => ({...prev, start_date: x.target.value}))} defaultValue={newschedule.start_date} className='input input-sm w-3/5'/>
              <span className='w-3/12'>End Date</span>
              <input type='text' placeholder='End Date' onChange={(x) => setNewschedule(prev => ({...prev, end_date: x.target.value}))} defaultValue={newschedule.end_date} className='input input-sm w-3/5'/>
          </div>

          <div className='flex gap-5 items-center'>
              <span className='w-3/12'>Daily Start</span>
              <input type='text' placeholder='Start Time (HH:mm)' onChange={(x) => setNewschedule(prev => ({...prev, start_time: x.target.value}))} defaultValue={newschedule.start_time} className='input input-sm w-3/5'/>
              <span className='w-3/12'>Daily End</span>
              <input type='text' placeholder='End Time (HH:mm)' onChange={(x) => setNewschedule(prev => ({...prev, end_time: x.target.value}))} defaultValue={newschedule.end_time} className='input input-sm w-3/5'/>
          </div>

          <div className='flex justify-between bg-base-100 rounded-md p-2 my-5'>
            <div className='flex flex-col'>
              <span className=''>Mon</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, monday: x.target.checked ? 1 : 0}))} checked={newschedule.monday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Tue</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, tuesday: x.target.checked ? 1 : 0}))} checked={newschedule.tuesday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Wen</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, wednesday: x.target.checked ? 1 : 0}))} checked={newschedule.wednesday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Tue</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, thursday: x.target.checked ? 1 : 0}))}  checked={newschedule.thursday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Fri</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, friday: x.target.checked ? 1 : 0}))} checked={newschedule.friday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Sat</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, saturday: x.target.checked ? 1 : 0}))} checked={newschedule.saturday === 1}/>
            </div>
            <div className='flex flex-col'>
              <span className=''>Sun</span>
              <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setNewschedule(prev => ({...prev, sunday: x.target.checked ? 1 : 0}))} checked={newschedule.sunday === 1}/>
            </div>
          </div>

          <div className='flex flex-col bg-base-100 rounded-md'>
            {locations?.map((loc) => {
              return(
                <div key={loc.id} className='flex gap-5 items-center p-2'>
                  <span>{loc.location_name}</span>
                  <div className='flex gap-3 wraper'>
                    {loc.zones?.map((item) => {
                      return(
                        <div key={item.id} className='flex flex-col justify-center'>
                          <span>{item.zone}</span>
                          <input onChange={() => updateZones(item.id)} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                        </div>
                      )
                    })}
                  </div>
                </div>
              )
            })}
          </div>
        </div>

        <div className='flex gap-5'>
            <button onClick={createSch} className="btnd bg-success w-28">Create</button>
        </div>
      </div>

    </div>
  
  )
}

export default PAEventSchedule