import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon } from '@heroicons/react/24/solid'
import axios from 'axios'
import JwtUtils from '../../components/JwtUtils'
import AlertMessage from '../../components/alertMessage'

const MessagePlaylist = () => {

  const user = JwtUtils.getNameFromToken(localStorage.getItem('authToken'))
   const [mediaplaylists, setMediaplaylists] = useState([])
   const [editplaylist, setEditplaylist] = useState({})
   const [audioList, setAudioList] = useState([])
   const [newplaylists, setNewPlaylists] = useState([])
   const [duration, setDuration] = useState("00:00")
   const [playlistName, setPlaylistName] = useState("")
   const [type, setType] = useState("Normal")
   const [toast, setToast] = useState(false)
   const [message, setMessage] = useState("")
   const [modeMessage, setModeMessage] = useState("")
  
   const [deleteId, setDeleteId] = useState(0)
   const [editId, setEditId] = useState(0)


  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/playlists`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log( response.data.data);
      setMediaplaylists(response.data.data.sort((a, b) => b.id - a.id));
    });
  }, [])

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.get(`${baseUrl}/getmediaplayback`, { headers: { Authorization: `${token}`}}).then((response) => {
      setAudioList(response.data.data.sort((a, b) => b.id - a.id));
    });
  }, [])


  const addToList = (id) => {
    const newlist = audioList?.find((x) => x.id === id);
    setNewPlaylists([newlist, ...newplaylists]);
  };

  const deleteFromList = (id) => {
    //console.log("delete id", id)
    const updatedList = newplaylists?.filter((x) => x.id !== id);
    setNewPlaylists(updatedList);
  };
  
 

  useEffect(() => {
    const totalDuration = newplaylists.reduce((acc, element) => acc + convertToSeconds(element.duration), 0);
    setDuration(totalDuration);
  }, [newplaylists])

  
  const convertToSeconds = (timeString) => {
    console.log('element : ', timeString); // e.g. '00:00:05' or '03:20'
    const parts = timeString.split(":").map(Number);
  
    let seconds = 0;
  
    if (parts.length === 3) {
      // HH:MM:SS
      const [hours, minutes, secs] = parts;
      seconds = hours * 3600 + minutes * 60 + secs;
    } else if (parts.length === 2) {
      // MM:SS
      const [minutes, secs] = parts;
      seconds = minutes * 60 + secs;
    } else if (parts.length === 1) {
      // Just seconds
      seconds = parts[0];
    }
  
    return seconds;
  };

  const convertSecondsToTime = (totalSeconds) => {
    
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  };


  const submitPlaylist = () => {
    const data = {
      name:playlistName,
      type:type,
      mediaid : newplaylists.map(item => item.id)
    }
    console.log(data);
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/playlists`, data, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log(response);
      setMediaplaylists([...mediaplaylists, response.data.data]);
      setNewPlaylists([])
      setMessage(response.data.message)
      setModeMessage("success")
      setToast(true)
      setTimeout(() => {
        setToast(false)
      }, 5000);
    });
  }

  const deletePlaylist = (id) => {
    setDeleteId(id);
    const modal = document.getElementById('deleteplaylist')
    modal.showModal();
  }

  const handleDelete = (id) => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.delete(`${baseUrl}/playlists/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
      if(response.status == 200){
        setMediaplaylists(mediaplaylists.filter((item) => item.id != id))
        setMessage(response.data.message)
        setModeMessage("success")
        setToast(true)
        setTimeout(() => {
          setToast(false)
        }, 5000);
      }
      else{
        setMessage(response.data.message)
        setModeMessage("error")
        setToast(true)
        setTimeout(() => {
          setToast(false)
        }, 5000);
      }
    });
  }

  const editePlaylist = (id) => {
    setEditId(id)
    const item = mediaplaylists?.find((x) => x.id === id)
    console.log("item", item)
    setEditplaylist(item)
    const modal = document.getElementById('editePlaylist')
    modal.showModal();
    
  }

    const deleteFromEditeList = (id) => {
    console.log("delete id", id)
    //const updatedList = editplaylist.plDetails.filter((x) => x.id !== id)
    setEditplaylist({...editplaylist, plDetails: editplaylist.plDetails.filter(x => x.id !== id)})
  }
  
  const handleUpdate = () => {
    var obj = {
      id:editplaylist.id,
      name:editplaylist.name,
      type:editplaylist.type,
      mediaID: editplaylist.plDetails.map(item => item.id)
    }
    console.log("handleUpdate", obj)
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.put(`${baseUrl}/playlists`, obj, { headers: { Authorization: `${token}`}}).then((response) => {
      if(response.status === 200){
        document.getElementById('editePlaylist').close()
        setMediaplaylists(response.data.data)
      }
    });
  }


  return (
    <>
      <div className='flex h-[77vh] gap-10'>

        <div className='relative border rounded-lg w-8/12 p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Play List</span>
          <div className='h-full mt-3 gap-2 overflow-auto scrollbar'>
            {mediaplaylists?.map((item, key) => {
              return(
                <div key={key} tabIndex={0} className="collapse rounded-md bg-base-100 mb-3">
                  <div className="flex justify-between text-md text-base-400 gap-5 collapse-title min-h-12 font-bold">
                    <span>{item.name}</span>
                    <div className='flex gap-2'>
                      <button className='text-info' onClick={() => editePlaylist(item.id)}><PencilSquareIcon className='w-5'/></button>
                      <button className='text-error' onClick={() => deletePlaylist(item.id)}><TrashIcon className='w-5'/></button>
                    </div>
                  </div>
                  <div className="collapse-content">
                    <table className='w-full'>
                      <thead className='text-left bg-base-300 p-2 text-base-100'>
                        <tr className='border-b'>
                          <th>Name</th>
                          <th>Type</th>
                          <th>PID Text</th>
                          <th>Audio Location</th>
                        </tr>
                      </thead>
                      <tbody>
                      {item.plDetails?.map((audio, ind) => {
                        return(
                        <tr key={ind} className='h-10'>
                          <td>{audio.mediaName}</td>
                          <td>{audio.mediaType}</td>
                          <td>{audio.mediaDescription}</td>
                          <td>{audio.mediaPath}</td>
                        </tr>
                        )
                      })}
                      </tbody>
                    </table>
                    
                  </div>
                </div>
              )
            })}
          </div>
        </div>

        <div className='flex flex-col gap-5 justify-between w-4/12'>
          <div className='relative h-3/5 border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Audio List</span>
              <div className='w-full h-full overflow-auto scrollbar pt-3'>
                {audioList?.map((item , key) => {
                  return(
                    <div key={key} className='flex justify-between p-2 mb-2 bg-base-100 rounded-lg'>
                      <span>{item.name}</span>
                      <button onClick={() => addToList(item.id)} className='flex items-center justify-center bg-accent rounded-full w-6 h-6 text-2xl pb-1'>+</button>
                    </div>
                  )
                })}
              </div>
            </div>
            <div className='flex flex-wrap items-start gap-3 h-2/5 border rounded-lg p-2 bg-base-200 overflow-auto scrollbar'>
                {newplaylists?.map((item , key) => {
                  return(
                    <div key={key} className='flex gap-3 items-center h-6 pl-2 bg-base-100 rounded-lg text-xs font-bold'>
                      <span>{item.name}</span>
                      <button onClick={() => deleteFromList(item.id)} className='bg-base-300 rounded-full w-6 h-6'>X</button>
                    </div>
                  )
                })}
            </div>
            <div className='flex'>
              <button onClick={() => (document.getElementById('createPlaylist')).showModal()} className="btnd bg-green-700 w-28">Submit</button>
            </div>
        </div>
      </div>

      <dialog id="createPlaylist" className="modal">
        <div className="modal-box w-11/12 max-w-2xl bg-base-100">
          <div className="relative border rounded-lg p-5">
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>New Media Playlist</span>
            <form method="dialog" className="flex flex-col gap-5">
              <input onChange={(e) => setPlaylistName(e.target.value)} type='text' placeholder='Playlist Name' className='bg-base-200'/>
              <select value={type} onChange={(e) => setType(e.target.value)} className='bg-base-200'>
                <option value="Normal">Normal</option>
                <option value="Emergency">Emergency</option>
              </select>
              {newplaylists?.map((item) => {
                console.log(item)
                return(
                  <div key={item.id} className='flex justify-between'>
                    <div className='flex gap-2'>
                      <span>{item.duration}</span>
                      <span>{item.name}</span>
                    </div>
                    <audio controls className="w-52 h-10" style={{ height: '30px' }} >
                          <source src={`${process.env.REACT_APP_AFTERSOX}/${item.name}.wav`} type="audio/mpeg" />
                          Your browser does not support the audio element.
                    </audio>
                  </div>
                )
              })}
              <div className='flex gap-5 modal-action'>
                <div className='flex flex-1 gap-2'>
                  <span className='text-base-300'>Total Duration :</span>
                  <span className='text-pink-500 font-bold'>{convertSecondsToTime(duration)}</span>
                </div>
                <button className="btnd w-20 bg-error">Close</button>
                <button onClick={() => submitPlaylist()} className="btnd w-20 bg-success">Submit</button>
              </div>
            </form>
          </div>
        </div>
      </dialog>
      
      <dialog id="editePlaylist" className="modal">
        <div className="modal-box w-11/12 max-w-2xl bg-base-100">
          <div className="relative border rounded-lg p-5">
          <span className='absolute left-8 bg-info-content px-5 rounded-lg text-white' style={{top:-15}}>Edite Playlist</span>
            <div className="flex flex-col gap-5">
             <input value={editplaylist?.name} onChange={(e) => setEditplaylist({...editplaylist, name: e.target.value})}  type='text' placeholder='Playlist Name' />
             <select value={editplaylist?.type} onChange={(e) => setEditplaylist({...editplaylist, type: e.target.value})} className=''>
                <option value="Normal">Normal</option>
                <option value="Emergency">Emergency</option>
              </select>
              {editplaylist.plDetails?.map((item) => {
                return(
                  <div key={item.id} className='flex justify-between'>
                    <div className='flex gap-2'>
                      <span>{item.duration}</span>
                      <span>{item.mediaName}</span>
                    </div>
                    <audio controls className="w-52 h-10" style={{ height: '30px' }} >
                          <source src={item.confirmedrecordingname} type="audio/mpeg" />
                          Your browser does not support the audio element.
                    </audio>
                    <button onClick={() => deleteFromEditeList(item.id)} className='bg-error rounded-full w-6 h-6'>X</button>
                  </div>
                )
              })}
              <div className='flex gap-5 modal-action'>
                <div className='flex flex-1 gap-2'>
                </div>
                <form method="dialog">
                  <button className="btnd w-20 bg-error">Close</button>
                </form>
                <button onClick={() => handleUpdate()} className="btnd w-20 bg-success">Update</button>
              </div>
            </div>
          </div>
        </div>
      </dialog>

      <dialog id="deleteplaylist" className="modal">
        <div className="modal-box w-full max-w-xl bg-base-100">
          <div className="relative border rounded-lg p-5">
            <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Delete Schedule id: {deleteId}</span>
            <form method="dialog" className="flex flex-col gap-5">
              <div className='flex justify-between modal-action'>
                <span>Are you sure to delete this schatual </span>
                <div className='flex gap-5'>
                  <button className="btnd w-20 bg-base-200">Close</button>
                  <button onClick={() => handleDelete(deleteId)} className="btnd w-20 bg-error">Delete</button>
                </div>
              </div>
            </form>
          </div>
        </div>
      </dialog>

      {toast && <AlertMessage message={message} type="sucssess" /> }
      {/* <Toast message={message} status={toast} mode={modeMessage} /> */}
    </>
  )
}

export default MessagePlaylist



