import React, { useState } from 'react'
import { MicrophoneIcon } from '@heroicons/react/24/solid'
import { useWebSocket } from '../../../context/WebSocketContext'

const SpeakNowModul = ({playZones}) => {

    const { sendMessage } = useWebSocket()
    const [ready, setReady] = useState(false)
    const [chanel, setChanel] = useState(false)
    const [chime, setChime] = useState('1')

    const openChanel =() => {
        
        // setChanel(true)
        // setTimeout(() => {
        //     setChanel(false)
        //     setReady(true)
        // }, 5000);

        console.log("start Open chanel ...")
    
        var randomId = Math.floor(1000 + Math.random() * 9000);
        let message = {
          messageId: randomId,
          messageType: "",
          commandStr: "speaknow",
          dataArr: [
            {
              recordingid:"",
              status: "",
              micname:"239.0.0.35:15001:1",
              zonelist: playZones,
              chimetype: chime,
              flag: "1",       
              priority: "6",
              pmcaddress:"239.0.0.35",
              pmcport:"15001",
              pmcchannel:'1',
              user: "amir",
            },
          ],
          deviceSelectionStr: "PA",
          moduleSelectionStr: "SPEAK_NOW",
        };
        sendMessage(JSON.stringify(message))
        setChanel(false)
        setReady(true)
    }

    const stopChanel =() => {
        setReady(false)
         let message = {
             commandStr: "close_mic",
             dataArr: [
                {
                    micname:"0",
                }
            ],
         }
        sendMessage(JSON.stringify(message))
        setReady(false)
    }

  return (
    <dialog id="speaknow" className="modal">
        <div className="modal-box w-full max-w-xl bg-neutral">
            <div className="relative border rounded-lg p-5">
                <span className='absolute left-8 bg-base-100 px-5 text-warning border rounded-lg' style={{top:-15}}>Speak Now</span>
                <div className="flex flex-col gap-5 pt-3">
                    <div>
                        {playZones.map((zone) => {
                            return(
                                <div className="w-28 h-5 badge badge-accent text-white" key={zone}>{zone}</div>
                            )
                        })}
                    </div>
                    <select className='input input-sm bg-base-100' value={1} onChange={(e) => setChime(e.target.value)}>
                        <option value="0">No chime</option>
                        <option value="1">chime 1</option>
                        <option value="2">chime 2</option>
                        <option value="3">chime 3</option>
                    </select>
                    <div className='flex items-center flex-col justify-center gap-2'>
                        {chanel && <span className='flex items-center gap-3'>Looking Chanel <span className="loading loading-dots loading-xs"></span> </span>}
                        {ready && <span className='flex items-center gap-3'>Chanel is ready with Mic:10.147.12.12</span>}
                        <MicrophoneIcon className={`h-20 ${ready ? "text-blue-700" : "text-error"}`}/>
                    </div>
                    <div className='flex justify-center gap-5'>
                        {!ready && !chanel ?
                            <form method="dialog">
                                <button  className="btnd w-28 bg-error">Close</button>
                            </form>
                            :
                            <button onClick={stopChanel} className="btnd w-28 bg-accent">Stop</button>
                        }
                        <button onClick={openChanel} className="btnd w-28 bg-success">Speak Now</button>
                    </div>

                </div>
            </div>
        </div>
    </dialog>
  )
}

export default SpeakNowModul