import React, { useRef, useState } from 'react'

const StepFive =  ({handleBack, handleNext, step, data, setData, setAudioFiles}) => {

  const fileInputRef = useRef(null);
  const [error, setError] = useState('')
 
  
   const handleUploadHI = (event) => {
     const file = event.target.files?.[0]

     if (file) {
      setAudioFiles((preaudio) => ({...preaudio, HI: file}))
       setData((prevState) => ({ ...prevState, audioHI: '/aftersox/'+ file.name }));
     } else {
       console.error('No file selected');
     }
   }
   const validation = () => {
    if(data.audioHI != ''){
      handleNext(step)
      setError('')
    }
    else{
      setError('Pleas import media file !')
    }
  }

  return (
    <div className='flex flex-col justify-between w-full items-center'>
    <div className='flex flex-col flex-1 gap-5 w-full h-full justify-center items-center'>
      <div className='flex flex-col items-center'>
        <span className='mb-3 text-2xl'>Record or import file in Bahasa Hindi</span>
        <small>Speak 10mm From Microphone</small>
        {error != '' && <span className='text-error'>{error}</span>}
      </div>
      {data.audioHI != '' && 
          <audio controls className="" style={{ height: '40px', width:"350px" }}>
            <source src={data.audioHI} type="audio/mpeg" />
            Your browser does not support the audio element.
          </audio>
          
        }
      <div className='flex gap-5'>
          <button className='btn btn-outline btn-info w-40'>START RECORDING</button>

          <label htmlFor="uploadHI" className="btn btn-outline btn-info w-40 overflow-hidden relative">IMPORT FILE
            <input id='uploadHI' className="hidden" type="file"  ref={fileInputRef} onChange={handleUploadHI} name="uploadBM" accept=".wav" />
          </label >
        </div>
    </div>
    <div className='flex gap-5'>
      <button onClick={() => handleBack(step)} className='w-20 btn btn-sm btn-info'>Back</button>
      {true && <button onClick={() => validation()} className='w-20 btn btn-sm btn-info' >Next</button>}
    </div>
  </div>
  )
}

export default StepFive