import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon, InformationCircleIcon } from '@heroicons/react/24/solid'
import axios from 'axios'
import { DataGrid } from '@mui/x-data-grid';

const HistoryAlarms = () => {
    const [alarms, setAlarms] = useState([])

    useEffect(() => {
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");
      axios.get(`${baseUrl}/alarm?key=history`, { headers: { Authorization: `${token}`}}).then((response) => {
          setAlarms(response.data.data.filter((x) => x.history == 1));
      })
    }, [])

    const columns = [
      { field: 'severity', headerName: 'Severity', width: 100, renderCell: (params) => {
        return(
          <div className={`${params.row.severity == 1 ? "bg-error" : params.row.severity == 2 ? "bg-warning" : params.row.severity == 3 ? "bg-warning-content" : "bg-success" }
            flex items-center justify-center font-bold text-lg rounded-full w-7 h-7 mt-3`}>!</div>
          
        )
      }},
      { field: 'name', headerName: 'Name', flex:1  },
      { field: 'createdOn', headerName: 'Create On', width: 250 },
      { field: 'clearedOn', headerName: 'Cleared On', width: 250 },
      { field: 'description', headerName: 'Fault', width: 150 },
      { field: 'action', headerName: 'Actions', width: 100 ,  
        renderCell: (params) => {
          return(
            <div className='flex gap-2 justify-center items-center h-12'>
              <PencilSquareIcon  className='w-5 text-info'/>
              <TrashIcon  className='w-5 text-error'/>
            </div>
          )
        }},
    ];


  return (
    <div className='relative border h-[77vh] bg-base-200 rounded-lg p-5'>
      <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>PIDS Alarms</span>
      <DataGrid rows={alarms} columns={columns} sx={{ border: 0 }} initialState={{...alarms.initialState, pagination: { paginationModel: { pageSize: 10 } }}} />
    </div>
  )
}

export default HistoryAlarms