import React, { useEffect, useState } from 'react'
import SingleMimic from './components/mimic'
import axios from 'axios'




const Mimic = () => {

  const[pids, setPids] = useState([])

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/mimic`, { headers: { Authorization: `${token}`}}).then((response) => {
      setPids(response.data);
    })
  }, [])


  return (
    <div className='relative border rounded-lg p-5 h-[80vh]'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 rounded-lg' style={{top:-15}}>PIDS Mimic</span>
        <div className='h-full gap-5 overflow-y-scroll pr-5'>
          {pids.map((item) => {
            return(
              <SingleMimic key={item.id} item={item} />
            )
          })}
        </div>
    </div>
  )
}

export default Mimic