import React, {useState } from 'react'
import StepOne from './stepOne'
import StepTwo from './stepTwo'
import StepThree from './stepThree'
import StepFour from './stepFour'
import StepSeven from './stepSeven'
import StepSix from './stepSix'
import StepFive from './stepFive'
import axios from 'axios'

const PlaylistBuilder = () => {

    const[step, setStep] = useState(2)
    const[uploaded, setUploaded] = useState(false)
    const[loading, setLoading] = useState(false)
    const[distributeData, setDistributeData] = useState([])


    const[audioFiles, setAudioFiles] = useState({
      "BM":null,
      "EN":null,
      "MA":null,
      "HI":null,
    })

    const[data, setData] = useState({
        "audioName":"",
        "textBM" : "",
        "textEN" : "",
        "textMA" : "",
        "textHI" : "",
        "audioBM":"",
        "audioEN":"",
        "audioMA":"",
        "audioHI":"",
    })

    const handleSubmit = () => {
      
      setLoading(true)

      const submitData = new FormData();
      submitData.append("BM", audioFiles.BM)
      submitData.append("EN", audioFiles.EN)
      submitData.append("MA", audioFiles.MA)
      submitData.append("HI", audioFiles.HI)
      submitData.append("create_by", "1")
      for (const key in data) {
        if (data.hasOwnProperty(key)) {
          submitData.append(key, data[key]);
        }
      }
      const baseUrl = process.env.REACT_APP_BASE_API;
      const token =  localStorage.getItem("authToken");


      axios.post(`${baseUrl}/store-media-playback`, submitData, { headers: { Authorization: `${token}`}}).then((response) => {
        if(response.status === 201){
          setDistributeData(response.data.data)
          setUploaded(true)
          setLoading(false)
        }
        else{
          setLoading(false)
        }
      });
      setTimeout(() => {
        setLoading(false)
      }, 8000);
    }

    const handleNext =(id) => {
        console.log("step", id)
      if (step >= 1 && step <= 6) {

        setStep( Number(id) + 1);
      }
    }

    const handleBack =(id) => {
      if (step >= 2 && step <= 7) {
        setStep( Number(id) - 1);
      }
    }

  return (
    <div className='relative border rounded-lg w-full h-[77vh] p-5 bg-base-200'>
      <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-13}}>Play List Builder</span>
      <div className='flex flex-col w-full h-full'>


        <ul className="steps steps-horizontal w-full pt-5 pb-10">
          <li id='1' className={`step ${step >= 1 && "step-success"}`} data-content="Step 1" />
          <li id='2' className={`step ${step >= 2 && "step-success"}`} data-content="Step 2" />
          <li id='3' className={`step ${step >= 3 && "step-success"}`} data-content="Step 3" />
          <li id='4' className={`step ${step >= 4 && "step-success"}`} data-content="Step 4" />
          <li id='5' className={`step ${step >= 5 && "step-success"}`} data-content="Step 5" />
          <li id='6' className={`step ${step >= 6 && "step-success"}`} data-content="Step 6" />
          <li id='7' className={`step ${step >= 7 && "step-success"}`} data-content="Step 7" />
        </ul>


        <div className='flex flex-1 justify-center px-10'>
          {step == 1 && <StepOne data={data} setData={setData} handleBack={handleBack} handleNext={handleNext} step={step}/>}
          {step == 2 && <StepTwo setAudioFiles={setAudioFiles} data={data} setData={setData} handleBack={handleBack} handleNext={handleNext} step={step}/>}
          {step == 3 && <StepThree setAudioFiles={setAudioFiles} data={data} setData={setData} handleBack={handleBack} handleNext={handleNext} step={step}/>}
          {step == 4 && <StepFour setAudioFiles={setAudioFiles} data={data} setData={setData} handleBack={handleBack} handleNext={handleNext} step={step}/>}
          {step == 5 && <StepFive setAudioFiles={setAudioFiles} data={data} setData={setData} handleBack={handleBack} handleNext={handleNext} step={step}/>}

          {step == 6 && <StepSix loading={loading} audioFiles={audioFiles} data={data} handleBack={handleBack} handleNext={handleNext} step={step} handleSubmit={handleSubmit} uploaded={uploaded}/>}
          {step == 7 && <StepSeven distributeData={distributeData} />}

        </div>

   
      </div>

    </div>
  )
}

export default PlaylistBuilder


