import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon } from '@heroicons/react/24/solid'
import axios from 'axios'
import { DataGrid } from '@mui/x-data-grid';

const Palogs = () => {
  const [logs, setLogs] = useState([])

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/eventlog?key=sys`, { headers: { Authorization: `${token}`}}).then((response) => {
      setLogs(response.data.data);
    })
  }, [])

  const columns = [
    { field: 'description', headerName: 'Fault', flex:1 },
    { field: 'create_on', headerName: 'Create On', width: 250 },
    { field: 'action', headerName: 'Actions', width: 100 ,  
      renderCell: (params) => {
        return(
          <div className='flex gap-2 justify-center items-center h-12'>
            <PencilSquareIcon  className='w-5 text-info'/>
            <TrashIcon  className='w-5 text-error'/>
          </div>
        )
      }},
  ];
  return (
    <div className='relative border h-[77vh] bg-base-200 rounded-lg p-5'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>PA Alarms</span>
        <DataGrid rows={logs} columns={columns} sx={{ border: 0 }} initialState={{...logs.initialState, pagination: { paginationModel: { pageSize: 10 } }}} />
    </div>
  )
}

export default Palogs