import React, { useEffect, useState } from 'react'
import { useWebSocket } from '../../../context/WebSocketContext'

const PlayEmergencyModul = ({playZones, playlists, stopZones, setStopZones}) => {

    const [ data, setData] = useState([])
    const [openId, setOpenId] = useState(null)
    const [chime, setChime] = useState('1')
    const { sendMessage, status } = useWebSocket()


    const selectAccordion = (id) => {
      
        setData(playlists.find((x) => x.id == id));
      
    };


    const handleToggle = (id) => {
        if (openId === id) {
          setOpenId(null); // Close if the same item is clicked
        } else {
          setOpenId(id); // Open the clicked item
        }
    }

    // useEffect(() => {
    //     console.log("data", data)
    // }, [data])
    

    const getMedias = () => {
        let medias = ""; 
        data.plDetails?.forEach((media) => {
          let audioPath = media.mediaPath.replace(/^"|"$/g, '');
          medias += `${audioPath},`;
        });
        const mediaPlaylist = medias.slice(0, -1);
        return mediaPlaylist; 
    }
    
    const getText = () => {
        let texts = []; 
        data.medias?.forEach((media) => {
          let text = media.pid_tex;
          texts.push(text); 
        });
        return texts; 
    }

    // Send to service by socket to play dva
    const handlePlayEmergency = () => {
        console.log("start play dva ...")
    
        let testPID = getText();

        var randomId = Math.floor(1000 + Math.random() * 9000);
        let message = {
          messageId: randomId,
          commandStr: "playemergencydva",
          dataArr: [
            {
              playlistId: String(data.id),
              mediaPlaylistName: data.name,
              wavfilename: String(getMedias()),
              zonelist: playZones,
              chimetype: chime,
              flag: "417",       
              priority: "5",
              timeoutms: "10000",
              pidsText: '',
              descText: testPID,
              user: "amir"
            },
          ],
          deviceSelectionStr: "PA",
          moduleSelectionStr: "PLAY_DVA_MODAL",
        }
        console.log("message form gui",message)
        sendMessage(JSON.stringify(message))

        var newStop = {id:randomId , label:'cancelplayemergencydva', zone: playZones}
        setStopZones(stopZones => [...stopZones, newStop]);
      }

  return (
    <dialog id="playemergency" className="modal">
        <div className="modal-box w-full max-w-3xl bg-error">
            <div className="relative border-2 border-error-content rounded-lg p-5">
                <span className='absolute left-8 bg-error-content px-5 text-warning border rounded-lg' style={{top:-15}}>Play Emergency</span>
                <form method="dialog" className="flex flex-col gap-5 pt-3">
                    <div>
                        {playZones.map((zone) => {
                            return(
                                <div className="w-28 h-5 badge badge-accent" key={zone}>{zone}</div>
                            )
                        })}
                    </div>
                    <select className="bg-error-content" value={chime} onChange={(e) => setChime(e.target.value)} >
                        <option value="0">No chime</option>
                        <option value="1">chime 1</option>
                        <option value="2">chime 2</option>
                        <option value="3">chime 3</option>
                    </select>
                    <div className='flex flex-col gap-2 h-[400px] bg-error-content p-3 rounded-lg'>
                        {playlists?.filter(x => x.type === "Emergency").map((each) => {
                            return(
                                <div key={each.id}  className='flex gap-5'>
                                <div  key={each.id} className={`collapse collapse-plus bg-red-700 ${openId === each.id ? "h-auto" : "h-10"}`}>
                                    <input type="checkbox" checked={openId === each.id} onChange={() => handleToggle(each.id)} />
                                    <div className="flex justify-between text-md text-warning gap-5 collapse-title font-bold">
                                        <span>{each.name}</span>
                                    </div>
                                    <div className={`collapse-content ${openId === each.id ? 'h-auto' : 'h-0 overflow-hidden'}`}>
                                        <table className='w-full'>
                                        <thead className='text-left bg-black'>
                                            <tr className='border-b'>
                                            <th>Name</th>
                                            <th>Audio Location</th>
                                            <th className='w-40'>Play Demo</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {each.plDetails?.map((audio, ind) => {
                                                return(
                                                <tr key={ind} className='h-10'>
                                                <td>{audio.mediaName}</td>
                                                <td>{audio.mediaPath}</td>
                                                <td>
                                                <audio controls className="w-52 h-10" style={{ height: '30px' }} >
                                                    {/* <source src={`${process.env.NEXT_PUBLIC_AFTERSOX}/${audio.path}.wav`} type="audio/mpeg" /> */}
                                                    <source src={audio.path} type="audio/mpeg" />
                                                </audio>
                                                </td>
                                                </tr>
                                                )
                                            })}
                                        </tbody>
                                        </table>
                                        
                                    </div>
                                </div>
                                <div className='flex justify-center items-center bg-red-900 w-10 h-10 rounded-lg'>
                                    <input onChange={() => selectAccordion(each?.id)} id={each.id} type="radio" name="radio-1" className="radio" />
                                </div>
                            </div>
                            )
                        })

                        }
                    </div>
                    <div className='flex gap-5'>
                        <button className="btnd w-20 bg-error-content">Close</button>
                        <button onClick={handlePlayEmergency} className={`btnd w-20 ${data.length == 0 ? "bg-slate-600" : "bg-success"}`} disabled={data.length == 0}>Play</button>
                    </div>

                </form>
            </div>
        </div>
    </dialog>
  )
}

export default PlayEmergencyModul