import React, { createContext, useState, useEffect, useContext } from 'react';

// Create a WebSocket context
const WebSocketContext = createContext(null);

// WebSocket provider component
export const WebSocketProvider = ({ children }) => {
  const [socket, setSocket] = useState(null);
  const [messages, setMessages] = useState([]);
  const [alarmsMessage, setAlarmsMessage] = useState(0);
  const [isConnected, setIsConnected] = useState(false);

useEffect(() => {
  const ws = new WebSocket('ws://10.103.104.31:9000');

  ws.onopen = () => {
    console.log('WebSocket connected');
    setIsConnected(true);
    setSocket(ws);
  };

  ws.onmessage = (event) => {
    const newMessage = JSON.parse(event.data);
    //console.log("Websocket Message", newMessage)

    if (newMessage.commandStr === "Zone_Status") {
      console.log('Zone_Status Message:', newMessage);
      setMessages((prevMessages) => [...prevMessages, newMessage]);
    }

    if (newMessage.commandStr === "Alarm") {
      //console.log('New alarm message:', newMessage);
      setAlarmsMessage((prev) => Number(prev) + 1);
    }
  }

  // Clean up the WebSocket connection on unmount
  return () => {
    ws.close();
  };
}, []);


  // Function to send messages
  const sendMessage = (message) => {
    if (socket && isConnected) {
      socket.send(message);
    } else {
      console.log('WebSocket is not connected');
    }
  };

  return (
    <WebSocketContext.Provider value={{ socket, messages, isConnected, sendMessage, setMessages, alarmsMessage }}>
      {children}
    </WebSocketContext.Provider>
  );
};

// Custom hook to use WebSocket context
export const useWebSocket = () => {
  return useContext(WebSocketContext);
};
