'use client'
import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon, TvIcon, XMarkIcon} from '@heroicons/react/24/solid'
import { CirclePicker } from 'react-color'
import axios from 'axios'
import { Rnd } from "react-rnd"
import AlertMessage from '../../components/alertMessage'


const Themplate = () => {

  const [message, setMessage] = useState('')
  const [error, setError] = useState('')

  const [color, setColor] = useState({display: false, color:''});
  const [fontcolor, setFontColor] = useState({display: false, color:''});
  const colors = ["#000", "#050C9C", "#e91e63", "#9c27b0", "#673ab7", "#3f51b5", "#2196f3", "#03a9f4", "#00bcd4", "#009688", "#4caf50", "#8bc34a", "#cddc39", "#ffeb3b", "#ffc107"]
  const [dragging, setDragging] = useState(false)
  const [modualDetails, setModualDetails] = useState({id:'0',pid_template_id:'0', key:'', x:0, y:0,width:'',height:'', bg_color:'#000', font_size:'80', font_color:'#FFF', pre_text:'We hope you have a pleasant journey;Have a nice day'})
  const [toast, setToast] = useState(false)
  const [templateID, setTemplateID] = useState(null)

  const [themplates, setThemplates] = useState([])
  const [components, setComponents] = useState([])

  const [preview, setPreview] = useState({id:0, name:'', description:'', components:[]})

  const [newtemplate, setNewtemplate] = useState({name:'', description:''})

  
  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/templates`, { headers: { Authorization: `${token}`}}).then((response) => {
      setThemplates(response.data);
    });
    axios.get(`${baseUrl}/template-components`, { headers: { Authorization: `${token}`}}).then((response) => {
      setComponents(response.data);
    });
  }, [])

  useEffect(() => {
    var data = themplates.find((x) => x.id == 1)
    if(data){
      setPreview(data)
    }
  }, [themplates])
  
  useEffect(() => {
    console.log("preview", preview)
    console.log("components", components)
  }, [preview, components])



  const handleModalNewThemplate = () => {
    console.log("newtemplate", newtemplate)
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/templates`, newtemplate, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("response", response)
      setThemplates(response.data)
    })
  }

  const savethemplate = () => {

    if(templateID != null){
 
      const data ={name:preview.name, description:preview.description ,components:preview.components}
      const baseUrl = process.env.REACT_APP_BASE_API
      const token =  localStorage.getItem("authToken")

      axios.put(`${baseUrl}/templates/${templateID}`, data, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log("response",response)
        if(response.status == 200){
          setMessage(response.data.message)
          setToast(true)
          setTimeout(() => {
            setToast(false)
          }, 3000);
        }
        else{
          setError(response.data.message)
          setToast(true)
          setTimeout(() => {
            setToast(false)
          }, 3000);
        }
        
      })
    }
    else{
      alert('Select a themplate !')
    }

  }

  const deletethemplate = (id) => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")
    axios.delete(`${baseUrl}/templates/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log("Delete", response.data)
      if(response.status == 200){
        setThemplates(response.data.templates)
        setMessage(response.data.message)
        setToast(true)
          setTimeout(() => {
            setToast(false)
          }, 3000);
      }
      else{
         setError(response.data.message)
          setToast(true)
          setTimeout(() => {
            setToast(false)
          }, 3000);
      }
    })
  }


  const handleDragStop = (id, newPosition) => {
    setPreview((prevState) => {
      const updatedComponents = prevState.components.map((component) => {
        if (component.id === id) {
          return { ...component, x: newPosition.x * 2, y: newPosition.y * 2 };
        }
        return component;
      });

      return { ...prevState, components: updatedComponents };
    });
  }

  const handleResizeStop = (id, newSize) => {
    setPreview((prevState) => {
      const updatedComponents = prevState.components.map((component) => {
        if (component.id === id) {
          return { ...component, width: newSize.width * 2 , height: newSize.height * 2 };
        }
        return component;
      });

      return { ...prevState, components: updatedComponents };
    });
  }

  const handleThemplate = (id) => {
    setTemplateID(id)
    var data = themplates.find((x) => x.id == id)
    if(data){

      setPreview(data)
    }
  }

  const handleModualDetails = (data) => {
    console.log(data)
    setModualDetails(data)
  }

  const updatePreview =(id)=>{

    setPreview((prevState) => ({...prevState, components: prevState.components.map((module) => module.id === id ? { ...module, ...modualDetails } : module)}))
    
  }

  const handleChangeColor = (hex) => {
    console.log("hex", hex)
    setColor((prevState) => ({...prevState, font_color: hex, display:false}))
    setModualDetails((prevState) => ({...prevState, bg_color: hex}))
    
  }

  const handleChangeFontColor = (hex) => {
    setFontColor((prevState) => ({...prevState, color: hex, display:false}))
    setModualDetails((prevState) => ({...prevState, font_color: hex}))
    
  }

  const handleColorPicker = () => {
    
    setColor((prevState) => ({...prevState, display: !color.display}))

  }

  const handleFontColorPicker = () => {
    
    setFontColor((prevState) => ({...prevState, display: !fontcolor.display}))

  }

   const handleFontSize = (value) => {
    setModualDetails((prevState) => ({...prevState, font_size: value}))
  }

  const removeComponent = (id) => {
    setPreview((prevState) => ({...prevState,components: prevState.components.filter(component => component.id !== id)}))
  }

  const addComponent = (id) => {
    console.log("Component id ", id)
    var newComponent = components.find(x => x.id == id)
    const result = newComponent ? { 
      component_name: newComponent.component_name, 
      x: newComponent.x, 
      y: newComponent.y, 
      width:newComponent.width, 
      height:newComponent.height,
      bg_color:newComponent.bg_color,
      font_color : newComponent.font_color,
      font_size : newComponent.font_size
    }: null
    console.log("New Component", result)

    setPreview(prevState => ({...prevState, components: [...prevState.components, result ]}))
  }

  return (
    <div className='flex gap-5 justify-between w-full h-full'>

      <div className='flex basis-3/12 flex-col w-[500px] gap-5 justify-between w-full h-[77vh]'>
        <div className='flex-1 relative border rounded-lg p-5 bg-base-200'>
            <span className='absolute left-8 bg-base-300 px-5 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Themplates</span>
            <div className='flex flex-col gap-2'>
              {themplates.map((themplate) => {
                return(
                  <div key={`tm_${themplate.id}`} className='flex justify-between'>
                    <div className='flex gap-2'>
                      <TvIcon className='w-5 text-info'/>
                      <span>{themplate.name}</span>
                    </div>
                    <div className='flex gap-2'>
                      <PencilSquareIcon onClick={(e) => handleThemplate(themplate.id)} className='w-5 text-info cursor-pointer'/>
                      <TrashIcon onClick={() => deletethemplate(themplate.id)} className='w-5 text-error cursor-pointer'/>
                    </div>
                  </div>
                )
              })}
            </div>
         
        </div>
      </div>

      <div className='basis-6/12 relative border h-[77vh] rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Editor</span>

            <div className='flex flex-col justify-between w-full h-full text-xs'>
              <div className='flex justify-between items-center border-b pb-5'>
                <input onChange={(e) => setPreview({...preview, name:e.target.value})} defaultValue={preview?.name} type='text' className='input input-sm' placeholder='Themplate Name' />
                <div className='flex gap-5'>
                  <button onClick={() => (document.getElementById('newThemplate')).showModal()} className='btn btn-sm btn-outline btn-accent '>Create New Themplate</button>
                  <button onClick={() => updatePreview(modualDetails.id)} className='btn btn-info btn-sm btn-outline'>Preview</button>
                  <button onClick={savethemplate} className='btn btn-success btn-sm btn-outline'>Save</button>
                </div>
              </div>
              <div className='flex flex-wrap gap-5 mt-5 h-[40px]'>
                {preview?.components?.map((item) => {
                  return(
                    <button key={item.id} onClick={() => handleModualDetails(item)} className="flex gap-3 badge badge-accent badge-outline">
                      {item.component_name}
                      <XMarkIcon onClick={() => removeComponent(item.id)} className='text-error w-4'/>
                    </button>
                  )
                })}
              </div>

              <div className='flex gap-5 items-center'>
                
              </div>

              <div className='relative place-self-end border w-[960px] h-[540px]'>
                {preview.components?.map((single) => {
                  return (
                    <Rnd size={{ width:`${single.width / 2}`, height:`${single.height / 2}`}} position={{ x:single.x / 2 , y: single.y / 2 }}
                    onDragStart={() => setDragging(true)}
                    onDragStop={(e, data) => handleDragStop(single.id, { x: data.x, y: data.y })}
                    onResizeStop={(e, direction, ref, delta, position) =>
                      handleResizeStop(single.id, { width: ref.offsetWidth, height: ref.offsetHeight })
                    }
                    onClick={() => handleModualDetails(single)}
                    style={{
                      display:'flex',
                      justifyContent:'center',
                      alignItems:'center',
                      color:`${single.font_color}`,
                      border: `${modualDetails.id == single.id ? "1px solid red" : "1px solid #ddd" } `,
                      background: `${single.bg_color}`,
                      cursor: dragging ? "move" : "default",
                    }}
                    bounds="parent"
                    key={single.id}>
                      {single.component_name}
                    </Rnd>
                  );
                })}
              </div>

          </div>
      </div>

      <div className='flex basis-3/12 flex-col gap-5 justify-between h-[77vh] w-[500px]'>

        <div className='relative border h-[220px] rounded-lg pt-5 px-2 bg-base-200 mb-5'>
            <span className='absolute left-8 bg-base-300 px-5 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Details : {modualDetails?.key}</span>
            <div className='flex justify-between'>
                <div className='flex gap-3 items-center'>
                  <span>Top :</span>
                  <span className='text-info font-bold'>{modualDetails?.y}</span>
                </div>
                <div className='flex gap-3 items-center'>
                  <span>Left :</span>
                  <span className='text-info font-bold'>{modualDetails?.x}</span>
                </div>
                <div className='flex gap-3 items-center'>
                  <span>Width :</span>
                  <span className='text-info font-bold'>{modualDetails?.width}</span>
                </div>
                <div className='flex gap-3 items-center'>
                  <span>Height :</span>
                  <span className='text-info font-bold'>{modualDetails?.height}</span>
                </div>
              </div>
              <div className='flex gap-5 items-center my-5'>
                  <span className='w-20'>Font Size</span>
                  <input onChange={(e) => handleFontSize(e.target.value)} defaultValue={modualDetails?.font_size}  type='text' className='input input-xs w-10 bg-base-100' />
              </div>
              <div className='relative flex gap-5 items-center my-5'>
                  <span className='w-20'>Background</span>
                  <button onClick={() => handleColorPicker()} className='btn btn-xs w-10 bg-black' style={{ backgroundColor:`${color.color ? color.color : modualDetails?.bg_color }`}}/>
                  <div className={`${!color.display && "hidden"} flex w-40 absolute bg-base-100 p-5 shadowFull`} style={{left:"0px", top:"30px", zIndex:100}}>
                    <CirclePicker colors={colors} onChangeComplete={(e) => handleChangeColor(e.hex)}  />
                  </div>
              </div>
              <div className='relative flex gap-5 items-center'>
                  <span className='w-20'>Font Color</span>
                  <button onClick={() => handleFontColorPicker()} className='btn btn-xs w-10 bg-black' style={{ backgroundColor:`${fontcolor.color ? fontcolor.color : modualDetails?.font_color }`}}/>
                  <div className={`${!fontcolor.display && "hidden"} flex w-40 absolute bg-base-100 p-5 shadowFull`} style={{left:"0px", top:"30px", zIndex:100}}>
                    <CirclePicker colors={colors} onChangeComplete={(e) => handleChangeFontColor(e.hex)} />
                  </div>
              </div>
            <div>
        </div>

        </div>

        <div className='flex-1 relative border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Components</span>
          <div className='flex flex-col gap-2 overflow-auto scrollbar h-[450px]'>
            {components.map((component) => {
              return(
                <div key={`pr_${component.id}`} className='flex justify-between border-b p-1'>
                  <span>{component.component_name}</span>
                  <div className='flex gap-2'>
                    <button onClick={() => addComponent(component.id)} className='leading-none btn btn-accent btn-xs text-white text-xl w-10 h-5'> + </button>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      </div>

        <dialog id="newThemplate" className="modal">
          <div className="modal-box w-full max-w-xl bg-base-100">
            <div className="relative border rounded-lg p-5">
              <span className='absolute left-8 bg-base-300 text-base-100 rounded-lg px-5' style={{top:-15}}>Create new themplate</span>
              <div className='flex flex-col gap-3 '>
                <input onChange={(e) => setNewtemplate({...newtemplate, name:e.target.value})} type='text' placeholder='Themplate name'/>
                <input onChange={(e) => setNewtemplate({...newtemplate, description:e.target.value})} type='text' placeholder='Themplate description'/>
              </div>
              <form method="dialog" className="flex flex-col gap-5">
             
                <div className='flex gap-3 modal-action'>
                  <button className="btnd bg-base-200 w-20">Close</button>
                  <button onClick={handleModalNewThemplate} className="btnd w-20 bg-success">Create</button> 
                </div>
              </form>
            </div>
          </div>
        </dialog>


      {toast && <AlertMessage message={message} time={3000} type="success" />}
      {error && <AlertMessage message={error} time={3000} type="error" />}
    </div>
  )
}


export default Themplate