import React, { useState } from 'react'
import { useWebSocket } from '../../../context/WebSocketContext'


const AdHocTextModul = ({playZones}) => {

    const { sendMessage } = useWebSocket()
    const [instantText, setInstantText] = useState('')

    const data =[
        {id:1, name:'Test 1', message:'This is test message 1'},
        {id:2, name:'Test 2', message:'This is test message 2'},
        {id:3, name:'Test 3', message:'This is test message'},
        {id:4, name:'Test 4', message:'This is test message'},
        {id:5, name:'Test 5', message:'This is test message'},
        {id:6, name:'Test 6', message:'This is test message'},
        {id:7, name:'Test 7', message:'This is test message'},
        {id:8, name:'Test 8', message:'This is test message'},
        {id:9, name:'Test 9', message:'This is test message'},
        {id:10, name:'Test 10', message:'This is test message'},

    ]

    const handleSelect = (id) => {
        const preMessage = data.find((x) => x.id === id)
        setInstantText(preMessage?.message)
    }

    const handleAdHoc = () => {
        var randomId = Math.floor(1000 + Math.random() * 9000);
        const message = {
            messageId: `${randomId}`,
            messageType: "Message",
            commandStr: "playAdhocText",
            dataArr: [
              {
                pidlist: ["SA01-GDU06-CC1-D1","SA01-GDU06-CC1-D2"],
                priority: "8",
                timeoutms: "60000",
                pidsText: [instantText, instantText, instantText],
                user: "Amir"
              },
            ],
            deviceSelectionStr: "PIDS_TCS"
        };
         sendMessage(JSON.stringify(message))
    }

  return (
    <dialog id="adhoctext" className="modal">
        <div className="modal-box w-full max-w-4xl bg-neutral flex gap-5">
            <div className="relative border rounded-lg p-5 flex-1">
                <span className='absolute left-8 bg-base-100 px-5 text-warning border rounded-lg' style={{top:-15}}>Ad Hoc Text</span>
                <div className="flex flex-col gap-5 pt-3">
                    <div>
                        {playZones.map((zone) => {
                            return(
                                <div className="w-28 h-5 badge badge-accent text-white" key={zone}>{zone}</div>
                            )
                        })}
                    </div>

                    <textarea value={instantText} onChange={(e) => setInstantText(e.target.value)} placeholder='PID text ...' className='bg-base-200 rounded-lg p-3 h-[200px]' />

                    <div className='flex gap-5'>
                        <form method="dialog">
                            <button  className="btnd w-28 bg-error">Close</button>
                            <button onClick={() => handleAdHoc()} className={`btnd w-28 ${instantText == '' ? "bg-slate-600" : "bg-success"}`} disabled={instantText == ''}>Send</button>
                        </form>
                    </div>

                </div>
            </div>
            <div className="relative border rounded-lg p-5 w-3/12">
                <span className='absolute left-8 bg-base-100 px-5 text-warning border rounded-lg' style={{top:-15}}>List Text</span>
                <div className='flex flex-col gap-3 items-start max-h-[300px] overflow-y-scroll'>
                    {data.map((item) => {
                        return(
                            <button key={item.id} onClick={() => handleSelect(item.id)}>{item.name}</button>
                        )
                    })}
                </div>
            </div>
        </div>
    </dialog>
  )
}

export default AdHocTextModul