import React, { useState, useRef, useEffect  } from 'react'
import { useWebSocket } from '../../context/WebSocketContext'
import { MicrophoneIcon } from '@heroicons/react/24/solid'

const StepTwo = ({handleBack, handleNext, step, data, setData, setAudioFiles}) => {
  const { sendMessage } = useWebSocket()
  const fileInputRef = useRef(null);
  const [error, setError] = useState('')
  const [started, setStarted] = useState(false)


  const [second, setSecond] = useState("00");
  const [minute, setMinute] = useState("00");
  const [counter, setCounter] = useState(0);




  const handleUploadBM = (event) => {
    const file = event.target.files?.[0]
    if (file) {
      setAudioFiles((preaudio) => ({...preaudio, BM: file}))
      setData((prevState) => ({ ...prevState, audioBM: '/aftersox/'+ file.name }));
    } else {
      console.error('No file selected');
    }
  }

  const validation = () => {
    if(data.audioBM != ''){
      handleNext(step)
      setError('')
    }
    else{
      setError('Pleas import media file !')
    }
  }

   useEffect(() => {
    console.log("Timer start ...")
    let intervalId;

    if (started) {
     intervalId = setInterval(() => {
        setCounter((prevCounter) => {
          const secondCounter = prevCounter % 60;
          const minuteCounter = Math.floor(prevCounter / 60);

          const computedSecond =
            String(secondCounter).padStart(2, "0");
          const computedMinute =
            String(minuteCounter).padStart(2, "0");

          setSecond(computedSecond);
          setMinute(computedMinute);

          return prevCounter + 1;
        });
      }, 1000)
    }

    return () => clearInterval(intervalId);
  }, [started])

  const startRecording = () => {
    console.info('Start recording ...')
    setStarted(true)
    var randomId = Math.floor(1000 + Math.random() * 9000);
    const message = {
      messageId: randomId,
      commandStr: "startrecording",
      dataArr: [
        {
          micname: "239.0.0.35:15001:1",
          chimetype: "2",
          flag: "1",
          priority: "9",
          pmcaddress: "239.0.0.35",
          pmcport:"15001",
          pmcchannel: "1"
        },
      ],
      deviceSelectionStr: "PA",
      moduleSelectionStr: "BM_RECORDING",
    };
    sendMessage(JSON.stringify(message))
  }

  const stopRecording =() => {
      setStarted(false)
       setCounter(0);
      setSecond("00")
      let message = {
        commandStr: "stoprecording",
        dataArr: [
          {
            //recordingid: `${resp.recordingId}`
          },
        ],
        deviceSelectionStr: "PA",
        moduleSelectionStr: "BM_RECORDING",
      }
    sendMessage(JSON.stringify(message))
  }

 


  return (
    <div className='flex flex-col justify-between w-full items-center'>
      <div className='flex flex-col flex-1 gap-5 w-full h-full justify-center items-center'>
        <div className='flex flex-col items-center'>
          <span className='mb-3 text-2xl'>Record or import file in Bahasa Malaysia</span>
          <small>Speak 10mm From Microphone</small>
          {error != '' && <span className='text-error'>{error}</span>}
        </div>
        {data.audioBM != '' && 
          <audio controls className="" style={{ height: '40px', width:"350px" }}>
            <source src={data.audioBM} type="audio/mpeg" />
            Your browser does not support the audio element.
          </audio>
          
        }
        <div>
           
        </div>
        <div className='flex gap-5'>
          <button onClick={started ? stopRecording : startRecording} className='btn btn-outline btn-info w-40'>
            {started ? "STOP" :"START RECORDING"}
            {started && <MicrophoneIcon className='w-6'/>}
            {started &&
              <>
                <span className="minute">{minute}</span>
                <span>:</span>
                <span className="second">{second}</span>
              </>
            }
          </button>

          <label htmlFor="uploadBM" className="btn btn-outline btn-info w-40 overflow-hidden relative">IMPORT FILE
            <input id='uploadBM' className="hidden" type="file"  ref={fileInputRef} onChange={handleUploadBM} name="uploadBM" accept=".wav" />
          </label >
        </div>
      </div>
      <div className='flex gap-5'>
        <button onClick={() => handleBack(step)} className='w-20 btn btn-sm btn-info'>Back</button>
        {true && <button onClick={() => validation()} className='w-20 btn btn-sm btn-info' >Next</button>}
      </div>
    </div>
  )
}

export default StepTwo