import { useWebSocket } from '../../../context/WebSocketContext'
import React, { useEffect, useState } from 'react'

const PlayDvaModul = ({playZones, playlists, setSelected, stopZones, setStopZones}) => {

    const [ data, setData] = useState([])
    const [openId, setOpenId] = useState(null)
    const [chime, setChime] = useState('1')
    const { sendMessage, status } = useWebSocket()

    //console.log('PlayList', playlists)

    const selectAccordion = (id) => {
      
        setData(playlists.find((x) => x.id == id));
      
    };

   

    const handleToggle = (id) => {
        if (openId === id) {
          setOpenId(null); // Close if the same item is clicked
        } else {
          setOpenId(id); // Open the clicked item
        }
      }


    const getMedias = () => {
        let medias = ""; 
        data.plDetails?.forEach((media) => {
          let audioPath = media.mediaPath.replace(/^"|"$/g, '');
          medias += `${audioPath},`;
        });
        const mediaPlaylist = medias.slice(0, -1);
        return mediaPlaylist; 
    }

    
    const getText = () => {
        let texts = []; 
        data.plDetails?.forEach((media) => {
          let text = media?.mediaDescription;
          texts.push(text); 
        });
        return texts; 
    }
  
    useEffect(()=>{
      getMedias();
      getText();
    },[playZones])


    // Send to service by socket to play dva
    const handlePlayDVA = () => {
        console.log("start play dva ...")
    
        let testPID = getText();

        var randomId = Math.floor(1000 + Math.random() * 9000);
        let message = {
          messageId: randomId,
          commandStr: "playdva",
          dataArr: [
            {
              playlistId: String(data.id),
              mediaPlaylistName: data.name,
              wavfilename: String(getMedias()),
              zonelist: playZones,
              chimetype: chime,
              flag: "1",       
              priority: "8",
              timeoutms: "60000",
              pidsText:  String(getText()),
              descText: testPID,
              user: "amir"
            },
          ],
          deviceSelectionStr: "PA",
          moduleSelectionStr: "PLAY_DVA_MODAL",
        };
        sendMessage(JSON.stringify(message))
        var newStop = {id:randomId , label:'cancelplaydva', zone: playZones}
        setStopZones(stopZones => [...stopZones, newStop]);
      }


  return (
    <dialog id="playdva" className="modal">
        <div className="modal-box w-full max-w-4xl bg-base-100">
            <div className="relative border rounded-lg p-5">
                <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Play DVA</span>
                <form method="dialog" className="flex flex-col gap-5 pt-3">
                    <div>
                        {playZones.map((zone) => {
                            return(
                                <div key={zone} className="w-28 h-5 badge badge-secondary badge-outline">{zone}</div>
                            )
                        })}
                    </div>
                    <select className="bg-base-200 px-3" value={chime} onChange={(e) => setChime(e.target.value)} >
                        <option value="0">No chime</option>
                        <option value="1">chime 1</option>
                        <option value="2">chime 2</option>
                        <option value="3">chime 3</option>
                    </select>
                    <div className='flex flex-col gap-2 h-[400px]'>

                        {playlists?.filter(x => x.type === "Normal").map((each, ind,) =>{
                            return (
                                <div key={each.id}  className='flex gap-5'>
                                    <div  key={each.id} className={`collapse collapse-plus bg-neutral ${openId === each.id ? "h-auto" : "h-10"}`}>
                                        <input type="checkbox" checked={openId === each.id} onChange={() => handleToggle(each.id)} />
                                        <div className="flex justify-between text-md text-base-100 gap-5 collapse-title font-bold">
                                            <span>{each.name}</span>
                                        </div>
                                        <div className={`collapse-content ${openId === each.id ? 'h-auto' : 'h-0 overflow-hidden'}`}>
                                            <table className='w-full'>
                                            <thead className='text-left bg-base-300'>
                                                <tr className='border-b'>
                                                <th>Name</th>
                                                <th>Audio Location</th>
                                                <th className='w-40'>Play Demo</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {each.plDetails?.map((audio, ind) => {
                                                    return(
                                                    <tr key={ind} className='h-10'>
                                                    <td>{audio.mediaName}</td>
                                                    <td>{audio.mediaPath}</td>
                                                    <td>
                                                    <audio controls className="w-52 h-10" style={{ height: '30px' }} >
                                                        <source src={`${process.env.REACT_APP_AFTERSOX}/${audio.mediaName}.wav`} type="audio/mpeg" />
                                                    </audio>
                                                    </td>
                                                    </tr>
                                                    )
                                                })}
                                            </tbody>
                                            </table>
                                            
                                        </div>
                                    </div>
                                    <div className='flex justify-center items-center bg-neutral w-10 h-10 rounded-full'>
                                        <input onChange={() => selectAccordion(each?.id)} id={each.id} type="radio" name="radio-1" className="radio bg-white" />
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                    <div className='flex gap-5'>
                        <button className="btnd w-20 bg-base-200">Close</button>
                        <button onClick={handlePlayDVA} className={`btnd w-20 ${data.length == 0 ? "bg-slate-600" : "bg-success"}`} disabled={data.length == 0}>Play</button>
                    </div>

                </form>
            </div>
        </div>
    </dialog>
  )
}

export default PlayDvaModul