import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';

const ProtectedRoute = ({ element }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(null); // null means loading initially

  // Function to check if the token is valid
  const isTokenValid = (token) => {
    if (!token) return false;
    try {
      const decoded = JSON.parse(atob(token.split('.')[1])); // Decode the token to check expiry
      const expiryTime = decoded.exp * 1000; // exp is in seconds, so convert it to milliseconds
      return expiryTime > Date.now(); // Check if the token has expired
    } catch (error) {
      return false; // If the token is invalid (corrupt or expired), return false
    }
  };

  useEffect(() => {
    const token = localStorage.getItem('authToken');
    setIsAuthenticated(isTokenValid(token)); 
    // setIsAuthenticated(true); 
  }, []); 

  if (isAuthenticated === null) {
    return <div>Loading...</div>; // Optional: Add a loading indicator while checking auth
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" />; // Redirect to login page if not authenticated
  }

  // If authenticated, render the protected element
  return element;
};

export default ProtectedRoute;
