
import { useEffect } from 'react'
import { useWebSocket } from '../../../context/WebSocketContext'

const StopModdul = ({stop}) => {
 
const {sendMessage } = useWebSocket()   

const stopVipa = () => {

    let message = {
      messageId: stop.id,
      commandStr: stop.label,
      dataArr:[{
        zone: stop.zone,
        user: "amir"
      }]
    }
      console.log("stop message -->", message);
     sendMessage(JSON.stringify(message))
     document.getElementById("stopmodul").close()
  }

  //   useEffect(() => {
  //    console.log("stopZones -->", stop);
  // }, [stop])

  return (
    <dialog id="stopmodul" className="modal">
        <div className="modal-box w-full max-w-xl bg-base-100">
            <div className="relative border rounded-lg p-5">
                <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Cancle</span>
                <div className='flex gap-5'>
                    <span>Are you sure want to cancle it ?</span>
                    <form method="dialog"> <button className="btnd w-20 bg-base-200">Close</button></form>
                    <button onClick={stopVipa}  className={`btnd w-20 bg-error`}>Yes</button>
                </div>
            </div>
        </div>
    </dialog>
  )
}

export default StopModdul

