import axios from 'axios';
import React, { useEffect, useState } from 'react'
import {CheckCircleIcon, ExclamationCircleIcon} from '@heroicons/react/24/solid'


const StepSeven =  ({distributeData}) => {

  const[vipaList, setVipaList] = useState([])
  const[loading, setLoading] = useState(false)
  const[uploaded, setUploaded] = useState(false)

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/getvipastation`, { headers: { Authorization: `${token}`}}).then((response) => {
      if(response.status === 200){
        setVipaList(response.data.data)
      }
    });
  }, [])
  
  const handleDistribute = () => {
    setLoading(true)
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.post(`${baseUrl}/distribute`, distributeData, { headers: { Authorization: `${token}`}}).then((response) => {
      if(response.status === 200){
        setVipaList(response.data.data)
        setLoading(false)
        setUploaded(true)
      }
      else{
        setLoading(false)
      }
    });
    
  }
  return (
    <div className='flex flex-col justify-between w-full items-center'>
      <div className='flex flex-col flex-1 gap-5 w-full h-full justify-center items-center'>
        <div className='flex flex-col items-center'>
          <span className='mb-3 text-2xl'>Distribute Vipedia</span>
          <small>Thisis step must distribute new wave files to all vipedia</small>
        </div>
        <div className='flex justify-center items-center w-full'>
          <table className='w-6/12 text-left border-separate border-spacing-2 bg-base-100'>
            <thead className='bg-black'>
              <tr>
                <th>Name</th>
                <th>Host</th>
                <th className='w-40'>Status</th>
                <th className='w-40'>Total</th>
                <th className='w-20'>Result</th>
              </tr>
            </thead>
            <tbody>
              {vipaList.map((vipa) => {
                return(
                  <tr key={vipa.id}>
                    <td>{vipa.name}</td>
                    <td>{vipa.hostname}</td>
                    <td>{vipa.live_status ? <span className='font-bold text-success'>Online</span> : <span className='font-bold text-error'>Offline</span>}</td>
                    <td>{loading ? <span className="loading loading-spinner text-warning"></span> : vipa.result }</td>
                    <td>{vipa.result == "4/4" ? <CheckCircleIcon className='text-success w-8'/> : <ExclamationCircleIcon className='text-error w-8'/>}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      </div>
      <div className='flex gap-5'>
        <button onClick={() => window.location.reload()} className='w-20 btn btn-sm btn-info' disabled={!uploaded}>Finish</button>
        {true && <button onClick={() => handleDistribute()} className='w-20 btn btn-sm btn-info' disabled={uploaded} >Distribute</button>}
      </div>
    </div>
  )
}

export default StepSeven