import axios from 'axios'

import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon } from '@heroicons/react/24/solid'
import AlertMessage from '../../components/alertMessage'
import { DataGrid } from '@mui/x-data-grid';


const PidList = () => {

  const [pids, setPids] = useState([])
  const [zones, setZones] = useState([])
  const [pid, setPid] = useState({})
  const [toast, setToast] = useState(false)
  const [message, setMessage] = useState("")
  const [newPID, setNewPID] = useState({code:'', zone_id:0, pid_type_id:0, name:'', display_name:'', screen_position:0, ip_address_gdu:'', ip_address_pid:'', profile_id:0, created_by:1})
    
  
  useEffect(() => {
      console.log(newPID)
      console.log("zones", zones)
    }, [newPID, zones])
    
    
    
    useEffect(() => {
      console.log(newPID)
    }, [newPID])
    
    
    
  const pagination = { page: 0, pageSize: 10 };
  const columns = [
      { field: 'id', headerName: 'Id', width: 80 },
      { field: 'code', headerName: 'Code', flex:1  },
      { field: 'display_name', headerName: 'Location Name', width: 150 },
      { field: 'zone_name', headerName: 'Zones', width: 150 },
      { field: 'pid_type_name', headerName: 'Type', width: 150 },
      { field: 'name', headerName: 'Name', width: 150 },
      { field: 'screen_position', headerName: 'Screen Position', width: 120 },
      { field: 'ip_address_gdu', headerName: 'GDU IP', width: 200 },
      { field: 'ip_address_pid', headerName: 'PID IP', width: 200 },
      { field: 'profile_name', headerName: 'Profile', width: 200 },
      { field: 'action', headerName: 'Actions', width: 100 ,  
        renderCell: (params) => {
          return(
            <div className='flex gap-2 justify-center items-center h-12'>
              <PencilSquareIcon onClick={() => selectForUpdate(params.row.id)} className='w-5 text-info'/>
              <TrashIcon onClick={() => (document.getElementById('deletePid')).showModal()} className='w-5 text-error'/>
            </div>
          )
        }},
  ];

  useEffect(() => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.get(`${baseUrl}/pid`, { headers: { Authorization: `${token}`}}).then((response) => {
        console.log('pid list', response.data.pids)
      setPids(response.data.pids);
    })
    axios.get(`${baseUrl}/getzones`, { headers: { Authorization: `${token}`}}).then((response) => {
      setZones(response.data.data);
    })
  }, [])

  useEffect(() => {
   console.log(pid)
  }, [pid])

//   const handleDelete = (id) => {
//     const baseUrl = process.env.REACT_APP_BASE_API;
//     const token =  localStorage.getItem("authToken");
//     axios.delete(`${baseUrl}/user/${id}`, { headers: { Authorization: `${token}`}}).then((response) => {
//       if(response.status == 200 ){
//         setUsers(users.filter((item) => item.id != id))
//         setMessage(response.data.message)
//         setModeMessage("success")
//         setToast(true)
//         setTimeout(() => {
//           setToast(false)
//         }, 5000);
//       }
//       else{
//         setMessage(response.data.message)
//         setModeMessage("error")
//         setToast(true)
//         setTimeout(() => {
//           setToast(false)
//         }, 5000);
//       }
//     });

//     setUsers(users.filter((item) => item.id != id))
//     setMessage('User Deleted! ')
//     setModeMessage("success")
//     setToast(true)
//     setTimeout(() => {
//       setToast(false)
//     }, 5000);


//   }

  const selectForUpdate = (id) => {
    var modal = document.getElementById('editePid') 
    modal.showModal()
    const data = pids.find((x) => x.id === id)
    setPid(data)

  }

  const handleUpdate = () => {
    const baseUrl = process.env.REACT_APP_BASE_API;
    const token =  localStorage.getItem("authToken");
    axios.put(`${baseUrl}/edit-pid/${pid.id}`, pid, { headers: { Authorization: `${token}`}}).then((response) => {
      console.log(response)
      if(response.status == 201){
        setPids(response.data.pids)
        setMessage(response.statusText)
        setToast(true)
        setTimeout(() => {
          setToast(false)
        }, 3000);
      }
      else{
        setMessage(response.statusText)
        setToast(true)
        setTimeout(() => {
          setToast(false)
        }, 3000);
      }
    });

  }

  return (
    <>

    <div className='relative border h-[77vh] bg-base-200 rounded-lg p-5'>
        <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Pids List</span>
        <div className='flex flex-col h-full justify-between'>
          <DataGrid rows={pids} columns={columns} sx={{ border: 0 }} initialState={{...pids.initialState, pagination: { paginationModel: { pageSize: 10 } }}}
        />
            <button onClick={() => (document.getElementById('newPid')).showModal()} className="mt-10 btnd w-28 bg-accent z-10">Register PID</button>
        </div>
         

        <dialog id="newPid" className={`modal`}>
          <div className="modal-box w-11/12 max-w-6xl bg-base-100 shadowFull">
              <div className="relative flex gap-5 border rounded-lg">
                <div className='flex flex-col p-5 w-6/12'>
                  <span className='absolute left-8 bg-base-100 px-5 rounded-lg' style={{top:-12}}>Edit Pid</span>
                  <form method="dialog" className="flex flex-col gap-5">
                    <input type='text' onChange={(e) => setNewPID({ ...newPID, code: e.target.value })} placeholder='Pid Code' />
                    <input type='text' onChange={(e) => setNewPID({ ...newPID, name: e.target.value })} placeholder='Name' />
                    <input type='text' onChange={(e) => setNewPID({ ...newPID, display_name: e.target.value })} placeholder='Display name' />
                    <select onChange={(e) => setNewPID({ ...newPID, profile_id: Number(e.target.value) })} >
                      <option value={1}>Platform</option>
                      <option value={2}>Concource</option>
                    </select>
                    <select onChange={(e) => setNewPID({ ...newPID, screen_position: Number(e.target.value) })} >
                      <option value={1}>Screen 1</option>
                      <option value={2}>Screen 2</option>
                    </select>
                    <input type='text' onChange={(e) => setNewPID({ ...newPID, ip_address_gdu: e.target.value })} placeholder='Pid Code' />
                    <input type='text' onChange={(e) => setNewPID({ ...newPID, ip_address_pid: e.target.value })} placeholder='Pid Code' />
                    <div className='flex gap-5'>
                      <button className="btnd w-20 bg-error">Close</button>
                      <button onClick={() => handleUpdate()} className="btnd w-20 bg-success">Submit</button>
                    </div>
                  </form>
                </div>
                <div className='flex flex-col p-5 w-6/12'>
                    <select onChange={(e) => setNewPID({ ...newPID, zone_id: Number(e.target.value) })} >
                      {zones?.map((zone) => {
                        return(
                          <option key={zone.id} value={zone.id}>{zone.zone}</option>
                        )
                      })}
                    </select>
                </div>
              </div>
          </div>
        </dialog>

        <dialog id="editePid" className={`modal`}>
          <div className="modal-box w-11/12 max-w-6xl bg-base-100 shadowFull">
              <div className="flex flex-col gap-5">
                  <div className='relative border rounded-lg p-5'>
                  <span className='absolute left-8 bg-base-200 px-5 rounded-lg' style={{top:-12}}>Edit Pid</span>
                  <form method="dialog" className="flex flex-col gap-5 pt-5">
                    <input type='text' onChange={(e) => setPid({ ...pid, code: e.target.value })} value={pid?.code} placeholder='Pid Code' />
                    <input type='text' onChange={(e) => setPid({ ...pid, display_name: e.target.value })} value={pid?.display_name} placeholder='Pid Code' />
                    <select onChange={(e) => setPid({ ...pid, profile_id: Number(e.target.value) })} value={pid.profile_id} className=''>
                      <option value={1}>Platform</option>
                      <option value={2}>Concource</option>
                    </select>
                    <select onChange={(e) => setPid({ ...pid, screen_position: Number(e.target.value) })} value={pid.screen_position} className=''>
                      <option value={1}>Screen 1</option>
                      <option value={2}>Screen 2</option>
                    </select>
                    <input type='text' onChange={(e) => setPid({ ...pid, ip_address_gdu: e.target.value })} value={pid?.ip_address_gdu} placeholder='Pid Code' />
                    <input type='text' onChange={(e) => setPid({ ...pid, ip_address_pid: e.target.value })} value={pid?.ip_address_pid} placeholder='Pid Code' />
                    <div className='flex gap-5'>
                      <button className="btnd w-20 bg-error">Close</button>
                      <button onClick={() => handleUpdate()} className="btnd w-20 bg-success">Submit</button>
                    </div>
                  </form>
                </div>
              </div>
          </div>
        </dialog>

        <dialog id="deletePid" className="modal">
          <div className="modal-box w-full max-w-xl bg-base-300">
            <div className="relative border rounded-lg p-5">
            <span className='absolute left-8 bg-base-300 px-5' style={{top:-15}}>Delete Pid:</span>
              <form method="dialog" className="flex flex-col gap-5">
                <div className='flex justify-between modal-action'>
                  <span>Are you sure to delete this pid </span>
                  <div className='flex gap-5'>
                    <button onClick={() => handleUpdate(pid)} className="btnd w-20 bg-error">Close</button>
                    <button  className="btnd w-20 bg-success">Delete</button> 
                  </div>
                </div>
              </form>
            </div>
          </div>
        </dialog>

    </div>

    {toast && <AlertMessage message={message} type="success" />}
    
    </>
  )
}

export default PidList