import React, { useEffect, useState } from 'react'
import { TrashIcon, PencilSquareIcon, CheckIcon, XMarkIcon } from '@heroicons/react/24/solid'
import axios from 'axios';



const MediaSchedule = () => {

  const [locations, setLocations] = useState([])
  const [playlists, setPlaylists] = useState([])
  const [schedules, setSchedules] = useState([])
  const [previwschedules, setPreviwSchedules] = useState([])
  const [pids, setPids] = useState([])
  const [newschedules, setNewschedules] = useState(
    { 
      name:"",
      playlist_id:"", 
      start_date:"", 
      end_date:"", 
      start_time:"", 
      end_time:"", 
      monday:true,
      tuesday:true,
      wednesday:true,
      thursday:true,
      friday:true,
      saturday:true,
      sunday:true,
      is_active:true,
      zones:[], 
      pid_list:[], 
      is_active: true 
    }
  )

  
 useEffect(() => {
  const baseUrl = process.env.REACT_APP_BASE_API;
  const token =  localStorage.getItem("authToken");
  axios.get(`${baseUrl}/mediaschedules`, { headers: { Authorization: `${token}`}}).then((response) => {
    setSchedules(response.data.data);
  })

  axios.get(`${baseUrl}/pid_playlist`, { headers: { Authorization: `${token}`}}).then((result) => {
    setPlaylists(result.data.data);
  })

  axios.get(`${baseUrl}/getLocations`, { headers: { Authorization: `${token}`}}).then((resultLocation) => {
    setLocations(resultLocation.data)
  })

}, [])

  const getPid = async () => {
    const baseUrl = process.env.REACT_APP_BASE_API
    const token =  localStorage.getItem("authToken")

    const promises = newschedules.zones.map(zone =>
      axios.get(`${baseUrl}/pid/zone/${zone}`, {
        headers: { Authorization: `${token}` },
      })
    )
    const responses = await Promise.all(promises);
    const items = responses.map(res => res.data.data);

    setPids(items);

  }

 const handleStatus= () => {

 }

 const editeSchedule= (id) => {
  setPreviwSchedules(schedules.find((sch) => sch.id === id))
 }

 const deleteSchedule= () => {
  
 }


 useEffect(() => {
  getPid();
}, [newschedules.zones])

useEffect(() => {
  
  console.log('previwschedules', previwschedules)

}, [previwschedules])

useEffect(() => {
  
  console.log('newschedules', newschedules)

}, [newschedules])

const updateZones = (id) => {
  console.log(id)
  if(previwschedules.length > 0){
    console.log('A')
    setPreviwSchedules(prev => {
      const isPresent = prev.zones.includes(id)
      return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
    })
  }
  else{
    console.log('B')
    setNewschedules(prev => {
      const isPresent = prev.zones.includes(id)
      return {...prev, zones: isPresent ? prev.zones.filter(zoneId => zoneId !== id) : [...prev.zones, id]}
    })
  }
  
}

  return (
    <div className='flex h-full gap-10'>
      <div className='relative border w-8/12 h-[75vh] rounded-lg p-5 scro'>
          <span className='absolute left-8 bg-base-300 px-5 text-base-100 border rounded-lg' style={{top:-15}}>Media Schedule</span>
          <div className='mt-3'>
            <div className='flex flex-col gap-2 w-[99%] mb-2'>
              <div className=''>
                  <input type='text' placeholder="Search"/>
              </div> 
              <div className='flex bg-base-300 h-8 border-b text-base-100 px-3 rounded-md'>
                  <div className='grow'>Name</div>
                  <div className='w-[150px]'>Start Date</div>
                  <div className='w-[150px]'>Start Time</div>
                  <div className='w-[150px]'>End Date</div>
                  <div className='w-[150px]'>End Time</div>
                  <div className='w-[150px] text-center'>Actions</div>
              </div> 
            </div>
            <div className='flex flex-col gap-3 overflow-auto scrollbar mt-3'>
              {
                schedules?.map((sch) => {
                  return(
                    <div key={sch.id} className='flex w-full bg-base-200 p-2 rounded-md'>
                      <div className='grow'>{sch.name}</div>
                      <div className='w-[150px]'>{sch.start_date}</div>
                      <div className='w-[150px]'>{sch.start_time}</div>
                      <div className='w-[150px]'>{sch.end_date}</div>
                      <div className='w-[150px]'>{sch.end_time}</div>
                      <div className='w-[150px] flex gap-1 justify-center'>
                        <input type="checkbox" onChange={() => handleStatus(sch.id)} className="toggle toggle-md h-5 toggle-success" checked={true} />
                        <PencilSquareIcon onClick={() => editeSchedule(sch.id)} className='w-5 text-info cursor-pointer'/>
                        <TrashIcon onClick={() => deleteSchedule(sch.id)} className='w-5 text-error cursor-pointer'/>
                      </div>
                    </div>
                  )
                })
              }
            </div>
          </div>
      </div>

      <div className='flex flex-col gap-5 justify-between w-4/12'>
        <div className='relative h-full border rounded-lg p-5 bg-base-200'>
          <span className='absolute left-8 bg-base-300 text-base-100 px-5 border rounded-lg' style={{top:-15}}>Schedule</span>
          <div className='flex flex-col gap-3 mt-5 overflow-auto scrollbar text-sm'>
            <div className='flex gap-5 items-center'>
                <span className='w-2/5'>Schedule Name</span>
                <input type='text' onChange={(x) => setPreviwSchedules(prev => ({...prev, name: x.target.value}))} placeholder='Schedule name' defaultValue={previwschedules.name} className='input input-sm w-3/5'/>
            </div>

            <div className='flex gap-5 items-center mb-5'>
                <span className='w-2/5'>Playlist Name</span>
                <select type='text' onChange={(x) => setPreviwSchedules(prev => ({...prev, playlist_id: x.target.value}))} value={previwschedules?.playlist_id?.toString()} className='input input-sm w-3/5'>
                  <option value='0'>Select play list</option>
                  {playlists?.map((item) => {
                    return(
                      <option key={item.id} value={item.id}>{item.name}</option>
                    )
                  })}
                </select>
            </div>

            <div className='flex gap-5 items-center'>
                <span className='w-3/12'>Start Date</span>
                <input type='text' placeholder='Start Date' onChange={(x) => setPreviwSchedules(prev => ({...prev, start_date: x.target.value}))} defaultValue={previwschedules.start_date} className='input input-sm w-3/5'/>
                <span className='w-3/12'>End Date</span>
                <input type='text' placeholder='End Date' onChange={(x) => setPreviwSchedules(prev => ({...prev, end_date: x.target.value}))} defaultValue={previwschedules.end_date} className='input input-sm w-3/5'/>
            </div>

            <div className='flex gap-5 items-center'>
                <span className='w-3/12'>Daily Start</span>
                <input type='text' placeholder='Start Time (HH:mm)' onChange={(x) => setPreviwSchedules(prev => ({...prev, start_time: x.target.value}))} defaultValue={previwschedules.start_time} className='input input-sm w-3/5'/>
                <span className='w-3/12'>Daily End</span>
                <input type='text' placeholder='End Time (HH:mm)' onChange={(x) => setPreviwSchedules(prev => ({...prev, end_time: x.target.value}))} defaultValue={previwschedules.end_time} className='input input-sm w-3/5'/>
            </div>

            <div className='flex justify-between bg-base-100 rounded-md p-2'>
              <div className='flex flex-col'>
                <span className=''>Mon</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, monday: x.target.checked ? 1 : 0}))} checked={previwschedules.monday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Tue</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, tuesday: x.target.checked ? 1 : 0}))} checked={previwschedules.tuesday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Wen</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, wednesday: x.target.checked ? 1 : 0}))} checked={previwschedules.wednesday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Tue</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, thursday: x.target.checked ? 1 : 0}))}  checked={previwschedules.thursday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Fri</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, friday: x.target.checked ? 1 : 0}))} checked={previwschedules.friday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Sat</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, saturday: x.target.checked ? 1 : 0}))} checked={previwschedules.saturday == 1}/>
              </div>
              <div className='flex flex-col'>
                <span className=''>Sun</span>
                <input type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5' onChange={(x) => setPreviwSchedules(prev => ({...prev, sunday: x.target.checked ? 1 : 0}))} checked={previwschedules.sunday == 1}/>
              </div>

            </div>

            <div className='flex flex-col bg-base-100 rounded-md'>
                  {locations?.map((loc) => {
                    return(
                      <div key={loc.id} className='flex gap-5 items-center p-2'>
                        <span>{loc.location_name}</span>
                        <div className='flex gap-3 wraper'>
                          {loc.zones?.map((item) => {
                            return(
                              <div key={item.id} className='flex flex-col justify-center'>
                                <span>{item.zone}</span>
                                <input onChange={() => updateZones(item.id)} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                              </div>
                            )
                          })}
                        </div>
                      </div>
                    )
                  })}
            </div>

            <span className='w-2/5'>Choose PID</span>
            <div className='flex flex-wrap gap-2 items-center bg-base-100 rounded-md p-2'>
                {pids.length > 0 ? pids?.map((item) => {
                  return(
                    <div key={item.id} className='flex gap-5 bg-accent p-2 rounded-md text-xs'>
                      <span className='text-base-100 font-bold'>{item.pids[0].zone}</span>
                        {item?.pids.map((box) => {
                          return(
                            <div key={box.id} className='flex flex-col'>
                              <span className='text-base-100'>D{box.screen_position}</span>
                              <input id={box.id} type='checkbox' className='checkbox checkbox-info bg-white w-5 h-5'/>
                            </div>
                          )
                        })}
                    </div>
                  )
                }): <span className='text-base-300 font-bold'>No any zone selected !</span> }
            </div>

          </div>
        </div>

        <div className='flex gap-5'>
            <button onClick={() => (document.getElementById('createPlaylist')).showModal()} className="btnd bg-success w-28">Submit</button>
            <button onClick={() => (document.getElementById('importMusic')).showModal()} className="btnd bg-accent w-40">Import New Media</button>
          </div>
      </div>

    </div>

  )
}

export default MediaSchedule